{"acquirer": [{"quote": "Bed Bath and Beyond, Inc., a Delaware corporation (the “Company”), entered into an Agreement and Plan of Merger", "location": "Form 8-K, Item 1.01, Merger Agreement", "relevance_score": 5}, {"quote": "the Company shall issue and deliver to all the equityholders or term loan creditors, as applicable under the terms of the Merger Agreement, of TCS as of immediately prior to the Closing", "location": "Form 8-K, Item 1.01, Merger Consideration", "relevance_score": 5}], "target": [{"quote": "Merger Sub will merge with and into TCS (the “Merger”), with TCS surviving such Merger as a wholly owned subsidiary of the Company", "location": "Form 8-K, Item 1.01, Merger Agreement", "relevance_score": 5}, {"quote": "The Container Store Holdings, LLC, a Delaware limited liability company (“TCS”)", "location": "Form 8-K, Item 1.01, Merger Agreement", "relevance_score": 5}], "consideration_type": [{"quote": "the Company shall issue and deliver to all the equityholders or term loan creditors, as applicable under the terms of the Merger Agreement, of TCS as of immediately prior to the Closing: (a) senior convertible notes (“Buyer Convertible Notes”) in an aggregate principal amount equal to $54,000,000 (the “Minimum Buyer Convertible Note Payment”) minus the Specified Senior Loan Payment Amount; (b) a number of shares of common stock, $0.0001 par value per share, of the Company (“Buyer Common Stock”)", "location": "Form 8-K, Item 1.01, Merger Consideration", "relevance_score": 5}], "cash_consideration": [{"quote": "each TCS Equity Security issued and outstanding immediately prior to the Effective Time shall be cancelled and extinguished and no consideration shall be delivered or deliverable in exchange therefor", "location": "Form 8-K, Item 1.01, Merger Consideration", "relevance_score": 4}, {"quote": "each TCS Equity Security issued and outstanding immediately prior to the Effective Time shall be cancelled and extinguished and shall be converted into the right to receive the applicable portion of the Merger Consideration", "location": "Form 8-K, Item 1.01, Merger Consideration", "relevance_score": 4}, {"quote": "“Merger Consideration” shall mean, collectively, the Equity Purchase Price and Note Purchase Price.", "location": "Exhibit 2.1, Section 1.05(d)", "relevance_score": 4}], "stock_exchange_ratio": [], "shareholder_vote_date": [{"quote": "THIS AGREEMENT AND PLAN OF MERGER (this “Agreement”) is made and entered into as of April 2, 2026", "location": "Exhibit 2.1, preamble", "relevance_score": 3}, {"quote": "Concurrently with the execution and delivery of this Agreement, the Company has delivered to Buyer a true, correct and complete copy of a written consent of the holders of more than 50% of the issued and outstanding Class A Units as of the date of this Agreement which satisfies all requirements under the DLLCA and the Organizational Documents of the Company necessary to approve the Merger and the Contemplated Transactions", "location": "Exhibit 2.1, Recital C", "relevance_score": 5}], "closing_conditions": [{"quote": "The obligations of TCS and the Company to consummate the transactions contemplated by the Merger Agreement are subject to the satisfaction or waiver of a number of customary conditions, including: (i) the absence of laws or orders restraining the consummation of the Merger, (ii) either (A) delivery of the Lender Transaction Approval or (B) (x) the occurrence of the Foreclosure and related restructuring in accordance with the Strict Foreclosure Agreement and (y) delivery of written consent from more than 50% of the holders of Class A Units of TCS following the Foreclosure and related restructuring (the “Post-Foreclosure Securityholder Written Consent”), (iii) TCS’s receipt of Authorized New Loans in an aggregate principal amount of no less than $55,000,000, which such New Loans shall be repaid in full the Closing via the issuance of Buyer Convertible Notes, (iv) the satisfaction of certain conditions set forth in the ABL Consent, (v) the Company’s receipt of a copy of the 2026 Audited Financial Statements and, if the Closing has not occurred on or prior to August 15, 2026, receipt of the Subsequent Unaudited Financial Statements for the fiscal quarter ended June 30, 2026 and (vi) the representations and warranties of TCS, Merger Sub and the Company being true and correct, subject to the materiality standards contained in the Merger Agreement, and TCS, Merger Sub and the Company having complied in all material respects with their respective obligations under the Merger Agreement.", "location": "Form 8-K, Item 1.01, Conditions to Merger", "relevance_score": 5}], "event_status": [{"quote": "pursuant to which, subject to the terms and conditions set forth therein, Merger Sub will merge with and into TCS", "location": "Form 8-K, Item 1.01, Merger Agreement", "relevance_score": 5}], "security_description": [{"quote": "all of the outstanding Class A Units of TCS (“TCS Equity Securities”)", "location": "Form 8-K, Item 1.01, Merger Consideration", "relevance_score": 5}], "effective_date": [], "available_options": [{"quote": "if the Lender Transaction Approval is obtained and the Foreclosure does not occur prior to the Closing, then (A) the Merger Consideration shall be issued and delivered to the Term Loan Creditors, which shall be in exchange for full and final satisfaction of its debt and all obligations owing under the Term Loan Credit Agreement and release of all liens created thereunder and (B) each TCS Equity Security issued and outstanding immediately prior to the Effective Time shall be cancelled and extinguished and no consideration shall be delivered or deliverable in exchange therefor", "location": "Form 8-K, Item 1.01, Merger Consideration", "relevance_score": 5}, {"quote": "if the Lender Transaction Approval is not obtained and the Foreclosure occurs prior to the Closing, then each TCS Equity Security issued and outstanding immediately prior to the Effective Time shall be cancelled and extinguished and shall be converted into the right to receive the applicable portion of the Merger Consideration as set forth in the allocation schedule and subject to the terms and the conditions set forth in the Merger Agreement", "location": "Form 8-K, Item 1.01, Merger Consideration", "relevance_score": 5}], "default_option": [], "election_deadline": [], "merger_subsidiary": [{"quote": "Falcon Merger Sub, LLC, a Delaware limited liability company and wholly owned subsidiary of the Company (“Merger Sub”)", "location": "Form 8-K, Item 1.01, Merger Agreement", "relevance_score": 5}, {"quote": "TCS Merger Sub, LLC, a Delaware limited liability company and wholly owned subsidiary of Buyer (“Merger Sub”)", "location": "Exhibit 2.1, preamble", "relevance_score": 5}], "cash_consideration_qualifications": [], "stock_exchange_ratio_type": [], "stock_exchange_ratio_qualifications": [], "other_consideration": [{"quote": "the Company shall issue and deliver to all the equityholders or term loan creditors, as applicable under the terms of the Merger Agreement, of TCS as of immediately prior to the Closing: (a) senior convertible notes (“Buyer Convertible Notes”) in an aggregate principal amount equal to $54,000,000 (the “Minimum Buyer Convertible Note Payment”) minus the Specified Senior Loan Payment Amount; (b) a number of shares of common stock, $0.0001 par value per share, of the Company (“Buyer Common Stock”)", "location": "Form 8-K, Item 1.01, Merger Consideration", "relevance_score": 5}, {"quote": "if the Lender Transaction Approval is obtained and the Foreclosure does not occur prior to the Closing, then (A) the Merger Consideration shall be issued and delivered to the Term Loan Creditors, which shall be in exchange for full and final satisfaction of its debt and all obligations owing under the Term Loan Credit Agreement and release of all liens created thereunder and (B) each TCS Equity Security issued and outstanding immediately prior to the Effective Time shall be cancelled and extinguished and no consideration shall be delivered or deliverable in exchange therefor", "location": "Form 8-K, Item 1.01, Merger Consideration", "relevance_score": 5}, {"quote": "if the Lender Transaction Approval is not obtained and the Foreclosure occurs prior to the Closing, then each TCS Equity Security issued and outstanding immediately prior to the Effective Time shall be cancelled and extinguished and shall be converted into the right to receive the applicable portion of the Merger Consideration as set forth in the allocation schedule and subject to the terms and the conditions set forth in the Merger Agreement", "location": "Form 8-K, Item 1.01, Merger Consideration", "relevance_score": 5}], "expected_closing": [{"quote": "We anticipate closing the acquisition of The Container Store, Elfa, and Closet Works in July 2026.", "location": "Exhibit 99.1, Letter to Shareholders", "relevance_score": 5}], "event_status_details": [{"quote": "On April 2, 2026 (the “Effective Date”), Bed Bath and Beyond, Inc., a Delaware corporation (the “Company”), entered into an Agreement and Plan of Merger (the “Merger Agreement”)", "location": "Form 8-K, Item 1.01, Merger Agreement", "relevance_score": 5}, {"quote": "The obligations of TCS and the Company to consummate the transactions contemplated by the Merger Agreement are subject to the satisfaction or waiver of a number of customary conditions", "location": "Form 8-K, Item 1.01, Conditions to Merger", "relevance_score": 5}], "agreement_name": [{"quote": "entered into an Agreement and Plan of Merger (the “Merger Agreement”)", "location": "Form 8-K, Item 1.01, Merger Agreement", "relevance_score": 5}], "agreement_date": [{"quote": "AGREEMENT AND PLAN OF MERGER
among
Bed Bath & Beyond, Inc.,
a Delaware corporation;
TCS Merger Sub, LLC,
a Delaware limited liability company;
and
The Container Store Holdings, LLC
a Delaware limited liability company;
Dated as of April 2, 2026", "location": "Exhibit 2.1, title page", "relevance_score": 5}], "original_filing_date": [], "related_entities": [{"quote": "Falcon Merger Sub, LLC, a Delaware limited liability company and wholly owned subsidiary of the Company (“Merger Sub”)", "location": "Form 8-K, Item 1.01, Merger Agreement", "relevance_score": 5}, {"quote": "TCS Merger Sub, LLC, a Delaware limited liability company and wholly owned subsidiary of Buyer (“Merger Sub”)", "location": "Exhibit 2.1, preamble", "relevance_score": 5}], "security_identifiers": []}

{"acquirer": [{"quote": "Amazon.com, Inc., a Delaware corporation (“Amazon” or “Parent”)", "location": "8-K, Item 1.01, Agreement and Plan of Merger", "relevance_score": 5}, {"quote": "a number of validly issued, fully paid and nonassessable shares of Parent Common Stock equal to the Exchange Ratio (the “Stock Consideration”)", "location": "8-K, Item 1.01, Merger Consideration", "relevance_score": 5}], "target": [{"quote": "Globalstar, Inc. (“Globalstar” or the “Company”) entered into an Agreement and Plan of Merger", "location": "8-K, Item 1.01, Agreement and Plan of Merger", "relevance_score": 5}, {"quote": "each share of Company Common Stock issued and outstanding immediately prior to the First Effective Time (other than Canceled Shares) shall be converted into the right to receive", "location": "EX-2.1, Section 3.1(a)(ii)", "relevance_score": 5}], "consideration_type": [{"quote": "At the First Effective Time, each share of Company Common Stock issued and outstanding immediately prior to the First Effective Time (other than shares of Company Common Stock that are owned by the Company or any of its subsidiaries or the Buyer Parties or any of their respective wholly owned subsidiaries (such shares, the “Canceled Shares”)) will be canceled and will cease to exist, and automatically be converted into the right to receive, at the election of the holder thereof in accordance with, and subject to the terms, conditions and procedures set forth in the Merger Agreement, including the adjustments described below, the following consideration (collectively with, if applicable, cash in lieu of fractional shares, the “Merger Consideration”):", "location": "8-K, Item 1.01, Merger Consideration", "relevance_score": 5}, {"quote": "Stockholders are entitled to elect to receive, for each Globalstar share, either $90.00 in cash or 0.3210 shares of Amazon stock (in each case subject to adjustment)", "location": "EX-99.2, Key Transaction Terms", "relevance_score": 5}], "cash_consideration": [{"quote": "“Per Share Cash Consideration” shall mean (a) $90.00 minus (b) the Per Share Adjustment Amount.", "location": "EX-2.1, Exhibit A, Definitions", "relevance_score": 5}, {"quote": "for each share of Company Common Stock and each Warrant Notional Common Share with respect to which an election to receive cash (a “Cash Election”) has been properly made and not properly changed, revoked or deemed revoked pursuant to Section 3.2(b) (collectively, the “Cash Election Shares”), an amount in cash equal to the Per Share Cash Consideration, without interest (the “Cash Consideration”);", "location": "EX-2.1, Section 3.1(a)(ii)(1)", "relevance_score": 5}], "stock_exchange_ratio": [{"quote": "for each share of Company Common Stock and each Warrant Notional Common Share with respect to which an election to receive Parent Common Stock (a “Stock Election”) has been properly made and not properly changed, revoked or deemed revoked pursuant to Section 3.2(b) (collectively, the “Stock Election Shares”), a number of validly issued, fully paid and nonassessable shares of Parent Common Stock equal to the Exchange Ratio (the “Stock Consideration”);", "location": "EX-2.1, Section 3.1(a)(ii)(2)", "relevance_score": 5}, {"quote": "“Exchange Ratio” shall mean:
(a) if the Parent Measurement Price is less than $280.38, (i) 0.3210 minus (ii) the quotient of (x) the Per Share Adjustment Amount divided by (y) the Parent Measurement Price; or
(b) if the Parent Measurement Price is greater than or equal to $280.38, the quotient of (i) (x) $90.00 minus (y) the Per Share Adjustment Amount divided by (ii) the Parent Measurement Price, rounded to four decimal places.", "location": "EX-2.1, Exhibit A, Definitions", "relevance_score": 5}], "shareholder_vote_date": [{"quote": "Following the execution of the Merger Agreement, on April 13, 2026, Thermo Funding II, LLC and certain other affiliated entities (collectively, “Thermo”), who collectively hold approximately 57.6% of the issued and outstanding shares of common stock, par value $0.0001 per share, of the Company (the “Company Common Stock”), executed and delivered to the Company a written consent (the “Written Consent”) adopting the Merger Agreement and approving the transactions contemplated thereby, including the Mergers.", "location": "8-K, Item 1.01, Globalstar Approvals", "relevance_score": 5}], "closing_conditions": [{"quote": "The respective obligations of each party hereto to consummate the Mergers are subject to the satisfaction or waiver by the Company and Parent at or prior to the First Effective Time of the following conditions:
(a) the Requisite Stockholder Approval shall have been obtained;
(b) any waiting period (or any extension thereof) applicable to the consummation of the Mergers under the HSR Act shall have expired or early termination thereof shall have been granted;
(c) the Registration Statement shall have become effective under the Securities Act, no stop order suspending the effectiveness of the Registration Statement shall have been issued by the SEC and remain in effect and no proceeding for that purpose shall have been initiated by the SEC with respect to the Registration Statement that has not been withdrawn;
(d) any Governmental Authorization required to be obtained prior to consummation of the Mergers in connection with the Mergers set forth in Section 7.1(d) of the Company Disclosure Letter (the “Required Governmental Authorizations”) shall have been obtained (in accordance with Section 7.1(d) of the Company Disclosure Letter) and shall remain in full force and effect;
(e) at least twenty (20) calendar days shall have elapsed since the Company mailed to the stockholders of the Company the Information Statement as contemplated by Regulation 14C of the Exchange Act (including Rule 14c-2 promulgated under the Exchange Act); and
(f) no Governmental Authority of competent jurisdiction shall have enacted, issued, promulgated, enforced or entered any Law or Order which is then in effect and has the effect of preventing, making illegal or enjoining the consummation of the Mergers.", "location": "EX-2.1, Section 7.1", "relevance_score": 5}, {"quote": "The respective obligations of Parent, Acquisition Sub I and Acquisition Sub II to consummate the Mergers are, in addition to the conditions set forth in Section 7.1, further subject to the satisfaction or waiver by Parent at or prior to the First Effective Time of the following conditions:", "location": "EX-2.1, Section 7.2", "relevance_score": 3}, {"quote": "(a) each of the representations and warranties of the Company contained in this Agreement, without giving effect to any materiality or “Company Material Adverse Effect” qualifications therein, shall be true and correct as of the date of this Agreement and at and as of the Closing as though made at and as of such time", "location": "EX-2.1, Section 7.2(a)", "relevance_score": 5}, {"quote": "(b) the Company shall have performed or complied, in all material respects, with its obligations required under this Agreement to be performed or complied with by the Company at or prior to the Closing;
(c) since the date of this Agreement, there shall not have occurred any Company Material Adverse Effect;
(d) Parent shall have received a certificate of the Company, signed by a duly authorized officer of the Company, dated as of the Closing Date, certifying that each of the conditions set forth in Section 7.2(a), Section 7.2(b), Section 7.2(c) and Section 7.2(e) have been satisfied; and
(e) (i) the Governmental Authorizations set forth in Item 1 of Section 7.2(e) of the Company Disclosure Letter shall have been obtained in accordance with the terms therein and shall remain in full force and effect and (ii) the actions set forth in Items 2-5 of Section 7.2(e) of the Company Disclosure Letter shall have been completed in accordance with the terms therein.", "location": "EX-2.1, Section 7.2", "relevance_score": 5}, {"quote": "The obligation of the Company to consummate the Mergers is, in addition to the conditions set forth in Section 7.1, further subject to the satisfaction or waiver by the Company at or prior to the First Effective Time of the following conditions:", "location": "EX-2.1, Section 7.3", "relevance_score": 3}, {"quote": "(a) each of the representations and warranties of Parent, Acquisition Sub I and Acquisition Sub II contained in this Agreement, without giving effect to any materiality or “Parent Material Adverse Effect” qualifications therein, shall be true and correct as of the date of this Agreement and at and as of the Closing as though made at and as of such time", "location": "EX-2.1, Section 7.3(a)", "relevance_score": 5}, {"quote": "(b) Parent, Acquisition Sub I and Acquisition Sub II shall have performed or complied, in all material respects, with its obligations required under this Agreement to be performed or complied with by Parent, Acquisition Sub I and Acquisition Sub II, as the case may be, at or prior to the Closing;
(c) since the date of this Agreement, there shall not have occurred any Parent Material Adverse Effect; and
(d) the Company shall have received a certificate of Parent, Acquisition Sub I and Acquisition Sub II, signed by a duly authorized officer of Parent, dated as of the Closing Date, certifying that each of the conditions set forth in Section 7.3(a), Section 7.3(b) and Section 7.3(c) have been satisfied.", "location": "EX-2.1, Section 7.3", "relevance_score": 5}, {"quote": "The consummation of the Mergers is subject to certain closing conditions set forth in the Merger Agreement, including, but not limited to: (a) the Company receiving the Requisite Stockholder Approval (which has been satisfied through the delivery of the Written Consent, as described above), (b) the expiration or termination of any waiting periods applicable to the consummation of the Mergers under the Hart-Scott-Rodino Antitrust Improvements Act of 1976 (the “HSR Act”) and the clearance or approval under certain specified antitrust, foreign investment and satellite and telecommunications laws, (c) the absence of any law or order that prevents, makes illegal or enjoins the consummation of the Mergers, (d) at least twenty (20) calendar days having elapsed since the Company’s mailing to the Company’s stockholders of the Information Statement, (e) the Registration Statement becoming effective under the Securities Act of 1933, as amended (the “Securities Act”), (f) the absence of a Company Material Adverse Effect or a Parent Material Adverse Effect and (g) the achievement by the Company of certain HIBLEO-4 satellite milestones.", "location": "8-K, Item 1.01, Conditions to the Mergers", "relevance_score": 5}], "event_status": [{"quote": "The transaction is expected to close in 2027, subject to the satisfaction of certain closing conditions, including receipt of regulatory approvals and the achievement by Globalstar of certain HIBLEO-4 replacement satellite milestones.", "location": "EX-99.1, Key Transaction Terms", "relevance_score": 5}], "security_description": [{"quote": "common stock, par value $0.0001 per share, of the Company (the “Company Common Stock”)", "location": "EX-2.1, Section 3.1(a)(i)", "relevance_score": 5}, {"quote": "Common Stock, par value $0.0001 per share	GSAT	NASDAQ", "location": "8-K, Securities registered pursuant to section 12(b) of the Act", "relevance_score": 5}], "effective_date": [], "available_options": [{"quote": "Stockholders are entitled to elect to receive, for each Globalstar share, either $90.00 in cash or 0.3210 shares of Amazon stock (in each case subject to adjustment)", "location": "EX-99.2, Key Transaction Terms", "relevance_score": 5}, {"quote": "“Per Share Cash Consideration” shall mean (a) $90.00 minus (b) the Per Share Adjustment Amount.", "location": "EX-2.1, Exhibit A, Definitions", "relevance_score": 5}, {"quote": "for each share of Company Common Stock and each Warrant Notional Common Share with respect to which an election to receive Parent Common Stock (a “Stock Election”) has been properly made and not properly changed, revoked or deemed revoked pursuant to Section 3.2(b) (collectively, the “Stock Election Shares”), a number of validly issued, fully paid and nonassessable shares of Parent Common Stock equal to the Exchange Ratio (the “Stock Consideration”);", "location": "EX-2.1, Section 3.1(a)(ii)(2)", "relevance_score": 5}], "default_option": [{"quote": "Any shares of Company Common Stock (other than any Canceled Shares) and any Warrant Notional Common Shares with respect to which the Exchange Agent has not received an effective, properly completed Election Form on or before 5:00 p.m. (New York City time) on the date that is three (3) Business Days prior to the Closing Date (or such other time and date as Parent and the Company shall mutually agree) (the “Election Deadline”) shall be deemed to be No Election Shares and the Holders of such No Election Shares shall be deemed to have made a Stock Election with respect to such No Election Shares.", "location": "EX-2.1, Section 3.2(b)(iv)", "relevance_score": 5}], "election_deadline": [{"quote": "The “Election Deadline” will be 5:00 p.m. (New York City time) on the date three (3) Business Days prior to the closing of the Mergers (or such other time and date as Parent and the Company shall mutually agree).", "location": "8-K, Item 1.01, Merger Consideration", "relevance_score": 5}], "merger_subsidiary": [{"quote": "Grapefruit Acquisition Sub I, Inc., a Delaware corporation and a direct wholly owned subsidiary of Parent (“Acquisition Sub I”), and Grapefruit Acquisition Sub II, LLC, a Delaware limited liability company and a direct wholly owned subsidiary of Parent (“Acquisition Sub II”", "location": "8-K, Item 1.01, Agreement and Plan of Merger", "relevance_score": 5}], "cash_consideration_qualifications": [{"quote": "for each share of Company Common Stock and each Warrant Notional Common Share with respect to which an election to receive Merger Consideration in the form of cash (a “ Cash Election ”) has been properly made in accordance with the procedures set forth in the Merger Agreement (collectively, the “ Cash Election Shares ”), an amount in cash equal to (x) $90.00 minus (y) the Per Share Adjustment Amount (if any) (the “ Per Share Cash Consideration ”), without interest (the “ Cash Consideration ”);", "location": "8-K, Item 1.01, Merger Consideration", "relevance_score": 5}, {"quote": "the “Per Share Adjustment Amount” will be an amount equal to the quotient of (a) the aggregate amount payable by the Company to Customer, if any, immediately following the completion of the Mergers in the event the Company does not achieve certain operational milestones, which amount is capped at a maximum of $110 million, divided by (b) aggregate number of shares of Company Common Stock to be converted into the right to receive Merger Consideration.", "location": "8-K, Item 1.01, Merger Consideration", "relevance_score": 5}, {"quote": "the Merger Consideration to be paid to holders of Cash Election Shares is subject to automatic proration adjustment such that the maximum number of shares of Company Common Stock eligible to be converted into the right to receive the Cash Consideration pursuant to the Merger Agreement is equal to forty percent (40%) of the aggregate number of shares of Company Common Stock issued and outstanding immediately prior to the First Effective Time (other than Canceled Shares)", "location": "8-K, Item 1.01, Merger Consideration", "relevance_score": 5}, {"quote": "No fractional shares of Parent Common Stock will be issued in the Mergers, and holders of Company Common Stock otherwise entitled to receive a fractional share of Parent Common Stock will receive a cash payment, without interest, in lieu thereof, as specified in the Merger Agreement.", "location": "8-K, Item 1.01, Merger Consideration", "relevance_score": 5}], "stock_exchange_ratio_type": [{"quote": "“Exchange Ratio” shall mean:
(a) if the Parent Measurement Price is less than $280.38, (i) 0.3210 minus (ii) the quotient of (x) the Per Share Adjustment Amount divided by (y) the Parent Measurement Price; or
(b) if the Parent Measurement Price is greater than or equal to $280.38, the quotient of (i) (x) $90.00 minus (y) the Per Share Adjustment Amount divided by (ii) the Parent Measurement Price, rounded to four decimal places.", "location": "EX-2.1, Exhibit A, Definitions", "relevance_score": 5}], "stock_exchange_ratio_qualifications": [{"quote": "“Parent Measurement Price” shall mean the volume weighted average price (VWAP), rounded to four decimal places, of Parent Common Stock as reported by Bloomberg L.P. and using the “Bloomberg Definition” calculation method on the VWAP function for the ticker “AMZN US Equity” over the twenty (20) consecutive trading day period that ends on (and includes) the second trading day immediately prior to the Closing Date.", "location": "EX-2.1, Exhibit A, Definitions", "relevance_score": 5}, {"quote": "“Exchange Ratio” shall mean:
(a) if the Parent Measurement Price is less than $280.38, (i) 0.3210 minus (ii) the quotient of (x) the Per Share Adjustment Amount divided by (y) the Parent Measurement Price; or
(b) if the Parent Measurement Price is greater than or equal to $280.38, the quotient of (i) (x) $90.00 minus (y) the Per Share Adjustment Amount divided by (ii) the Parent Measurement Price, rounded to four decimal places.", "location": "EX-2.1, Exhibit A, Definitions", "relevance_score": 5}, {"quote": "the “Per Share Adjustment Amount” will be an amount equal to the quotient of (a) the aggregate amount payable by the Company to Customer, if any, immediately following the completion of the Mergers in the event the Company does not achieve certain operational milestones, which amount is capped at a maximum of $110 million, divided by (b) aggregate number of shares of Company Common Stock to be converted into the right to receive Merger Consideration.", "location": "8-K, Item 1.01, Merger Consideration", "relevance_score": 5}, {"quote": "No fractional shares of Parent Common Stock will be issued in the Mergers, and holders of Company Common Stock otherwise entitled to receive a fractional share of Parent Common Stock will receive a cash payment, without interest, in lieu thereof, as specified in the Merger Agreement.", "location": "8-K, Item 1.01, Merger Consideration", "relevance_score": 5}], "other_consideration": [], "expected_closing": [{"quote": "The transaction is expected to close in 2027, subject to the satisfaction of certain closing conditions, including receipt of regulatory approvals and the achievement by Globalstar of certain HIBLEO-4 replacement satellite milestones.", "location": "EX-99.1, Key Transaction Terms", "relevance_score": 5}], "event_status_details": [{"quote": "On April 13, 2026, Globalstar, Inc. (“Globalstar” or the “Company”) entered into an Agreement and Plan of Merger", "location": "8-K, Item 1.01, Agreement and Plan of Merger", "relevance_score": 5}, {"quote": "Following the execution of the Merger Agreement, on April 13, 2026, Thermo executed and delivered to the Company the Written Consent adopting the Merger Agreement and approving the transactions contemplated thereby, including the Mergers.", "location": "8-K, Item 1.01, Support Agreement", "relevance_score": 5}, {"quote": "The transaction is expected to close in 2027, subject to the satisfaction of certain closing conditions, including receipt of regulatory approvals and the achievement by Globalstar of certain HIBLEO-4 replacement satellite milestones.", "location": "EX-99.1, Key Transaction Terms", "relevance_score": 5}], "agreement_name": [{"quote": "AGREEMENT AND PLAN OF MERGER", "location": "EX-2.1, title", "relevance_score": 5}], "agreement_date": [{"quote": "Dated as of April 13, 2026", "location": "EX-2.1, title", "relevance_score": 5}], "original_filing_date": [], "related_entities": [{"quote": "Grapefruit Acquisition Sub I, Inc., a Delaware corporation and a direct wholly owned subsidiary of Parent (“Acquisition Sub I”), and Grapefruit Acquisition Sub II, LLC, a Delaware limited liability company and a direct wholly owned subsidiary of Parent (“Acquisition Sub II”", "location": "8-K, Item 1.01, Agreement and Plan of Merger", "relevance_score": 5}, {"quote": "Thermo Funding II, LLC and certain other affiliated entities (collectively, “Thermo”), who collectively hold approximately 57.6% of the issued and outstanding shares of common stock, par value $0.0001 per share, of the Company", "location": "8-K, Item 1.01, Globalstar Approvals", "relevance_score": 3}], "security_identifiers": [{"quote": "Common Stock, par value $0.0001 per share	GSAT	NASDAQ", "location": "8-K, Securities registered pursuant to section 12(b) of the Act", "relevance_score": 5}]}

{"acquirer": [{"quote": "Amazon.com, Inc., a Delaware corporation (“Amazon” or “Parent”)", "location": "8-K, Item 1.01, Agreement and Plan of Merger", "relevance_score": 5}, {"quote": "Immediately following the First Effective Time, the Surviving Corporation shall pay, in cash, to each holder of record of Company Preferred Stock as of immediately prior to the First Effective Time", "location": "EX-2.1, Section 3.4(b)", "relevance_score": 3}], "target": [{"quote": "Globalstar, Inc. (“Globalstar” or the “Company”) entered into an Agreement and Plan of Merger", "location": "8-K, Item 1.01, Agreement and Plan of Merger", "relevance_score": 5}, {"quote": "each share of Perpetual Preferred Stock, Series A, $0.0001 par value per share, of the Company (the “Company Preferred Stock”) outstanding shall be converted into the right to receive a liquidating distribution", "location": "EX-2.1, Section 3.4(a)", "relevance_score": 5}], "consideration_type": [{"quote": "Immediately following the First Effective Time, each share of Perpetual Preferred Stock, Series A, $0.0001 par value per share, of the Company (the “Company Preferred Stock”) outstanding shall be converted into the right to receive a liquidating distribution in the initial amount of the liquidation preference of $1,000 per share in cash, as increased by accrued dividends, pursuant to the Certificate of Designation of Perpetual Preferred Stock, Series A (as amended, the “Certificate of Designation”).", "location": "EX-2.1, Section 3.4(a)", "relevance_score": 5}], "cash_consideration": [{"quote": "each share of Perpetual Preferred Stock, Series A, $0.0001 par value per share, of the Company (the “Company Preferred Stock”) outstanding shall be converted into the right to receive a liquidating distribution in the initial amount of the liquidation preference of $1,000 per share in cash, as increased by accrued dividends", "location": "EX-2.1, Section 3.4(a)", "relevance_score": 5}], "stock_exchange_ratio": [{"quote": "Immediately upon receipt by each holder of its liquidating distribution, all shares of Company Preferred Stock owned by such holder shall be canceled and shall cease to exist, and such holder of Company Preferred Stock will not be entitled to any other amounts from the Surviving Corporation or Parent.", "location": "EX-2.1, Section 3.4(b)", "relevance_score": 5}, {"quote": "the Surviving Corporation shall pay, in cash, to each holder of record of Company Preferred Stock as of immediately prior to the First Effective Time, an amount equal to the liquidation preference (including all accrued and unpaid dividends as of the First Effective Time) per share as set forth in the Certificate of Designation, in full satisfaction of all rights of such holder with respect to such shares of Company Preferred Stock.", "location": "EX-2.1, Section 3.4(b)", "relevance_score": 5}], "shareholder_vote_date": [{"quote": "Following the execution of the Merger Agreement, on April 13, 2026, Thermo Funding II, LLC and certain other affiliated entities (collectively, “Thermo”), who collectively hold approximately 57.6% of the issued and outstanding shares of common stock, par value $0.0001 per share, of the Company (the “Company Common Stock”), executed and delivered to the Company a written consent (the “Written Consent”) adopting the Merger Agreement and approving the transactions contemplated thereby, including the Mergers.", "location": "8-K, Item 1.01, Globalstar Approvals", "relevance_score": 5}, {"quote": "The delivery of the Written Consent constitutes all required approvals of the Company’s stockholders under the Company’s organizational documents, Delaware law and the Merger Agreement necessary to consummate the Mergers. No further approval of the Company’s stockholders is required or will be sought.", "location": "8-K, Item 1.01, Globalstar Approvals", "relevance_score": 5}], "closing_conditions": [{"quote": "The respective obligations of each party hereto to consummate the Mergers are subject to the satisfaction or waiver by the Company and Parent at or prior to the First Effective Time of the following conditions:
(a) the Requisite Stockholder Approval shall have been obtained;
(b) any waiting period (or any extension thereof) applicable to the consummation of the Mergers under the HSR Act shall have expired or early termination thereof shall have been granted;
(c) the Registration Statement shall have become effective under the Securities Act, no stop order suspending the effectiveness of the Registration Statement shall have been issued by the SEC and remain in effect and no proceeding for that purpose shall have been initiated by the SEC with respect to the Registration Statement that has not been withdrawn;
(d) any Governmental Authorization required to be obtained prior to consummation of the Mergers in connection with the Mergers set forth in Section 7.1(d) of the Company Disclosure Letter (the “Required Governmental Authorizations”) shall have been obtained (in accordance with Section 7.1(d) of the Company Disclosure Letter) and shall remain in full force and effect;
(e) at least twenty (20) calendar days shall have elapsed since the Company mailed to the stockholders of the Company the Information Statement as contemplated by Regulation 14C of the Exchange Act (including Rule 14c-2 promulgated under the Exchange Act); and
(f) no Governmental Authority of competent jurisdiction shall have enacted, issued, promulgated, enforced or entered any Law or Order which is then in effect and has the effect of preventing, making illegal or enjoining the consummation of the Mergers.", "location": "EX-2.1, Section 7.1", "relevance_score": 5}, {"quote": "(b) the Company shall have performed or complied, in all material respects, with its obligations required under this Agreement to be performed or complied with by the Company at or prior to the Closing;
(c) since the date of this Agreement, there shall not have occurred any Company Material Adverse Effect;
(d) Parent shall have received a certificate of the Company, signed by a duly authorized officer of the Company, dated as of the Closing Date, certifying that each of the conditions set forth in Section 7.2(a), Section 7.2(b), Section 7.2(c) and Section 7.2(e) have been satisfied; and
(e) (i) the Governmental Authorizations set forth in Item 1 of Section 7.2(e) of the Company Disclosure Letter shall have been obtained in accordance with the terms therein and shall remain in full force and effect and (ii) the actions set forth in Items 2-5 of Section 7.2(e) of the Company Disclosure Letter shall have been completed in accordance with the terms therein.", "location": "EX-2.1, Section 7.2", "relevance_score": 5}, {"quote": "(b) Parent, Acquisition Sub I and Acquisition Sub II shall have performed or complied, in all material respects, with its obligations required under this Agreement to be performed or complied with by Parent, Acquisition Sub I and Acquisition Sub II, as the case may be, at or prior to the Closing;
(c) since the date of this Agreement, there shall not have occurred any Parent Material Adverse Effect; and
(d) the Company shall have received a certificate of Parent, Acquisition Sub I and Acquisition Sub II, signed by a duly authorized officer of Parent, dated as of the Closing Date, certifying that each of the conditions set forth in Section 7.3(a), Section 7.3(b) and Section 7.3(c) have been satisfied.", "location": "EX-2.1, Section 7.3", "relevance_score": 5}, {"quote": "The consummation of the Mergers is subject to certain closing conditions set forth in the Merger Agreement, including, but not limited to: (a) the Company receiving the Requisite Stockholder Approval (which has been satisfied through the delivery of the Written Consent, as described above), (b) the expiration or termination of any waiting periods applicable to the consummation of the Mergers under the Hart-Scott-Rodino Antitrust Improvements Act of 1976 (the “HSR Act”) and the clearance or approval under certain specified antitrust, foreign investment and satellite and telecommunications laws, (c) the absence of any law or order that prevents, makes illegal or enjoins the consummation of the Mergers, (d) at least twenty (20) calendar days having elapsed since the Company’s mailing to the Company’s stockholders of the Information Statement, (e) the Registration Statement becoming effective under the Securities Act of 1933, as amended (the “Securities Act”), (f) the absence of a Company Material Adverse Effect or a Parent Material Adverse Effect and (g) the achievement by the Company of certain HIBLEO-4 satellite milestones.", "location": "8-K, Item 1.01, Conditions to the Mergers", "relevance_score": 5}], "event_status": [{"quote": "The transaction is expected to close in 2027, subject to the satisfaction of certain closing conditions, including receipt of regulatory approvals and the achievement by Globalstar of certain HIBLEO-4 replacement satellite milestones.", "location": "EX-99.1, Key Transaction Terms", "relevance_score": 5}], "security_description": [{"quote": "Perpetual Preferred Stock, Series A, $0.0001 par value per share, of the Company (the “Company Preferred Stock”)", "location": "EX-2.1, Section 3.4(a)", "relevance_score": 5}], "effective_date": [], "available_options": [{"quote": "Immediately following the First Effective Time, each share of Perpetual Preferred Stock, Series A, $0.0001 par value per share, of the Company (the “Company Preferred Stock”) outstanding shall be converted into the right to receive a liquidating distribution in the initial amount of the liquidation preference of $1,000 per share in cash, as increased by accrued dividends", "location": "EX-2.1, Section 3.4(a)", "relevance_score": 5}], "default_option": [], "election_deadline": [], "merger_subsidiary": [{"quote": "Grapefruit Acquisition Sub I, Inc., a Delaware corporation and a direct wholly owned subsidiary of Parent (“Acquisition Sub I”), and Grapefruit Acquisition Sub II, LLC, a Delaware limited liability company and a direct wholly owned subsidiary of Parent (“Acquisition Sub II”", "location": "8-K, Item 1.01, Agreement and Plan of Merger", "relevance_score": 5}], "cash_consideration_qualifications": [{"quote": "the Surviving Corporation shall pay, in cash, to each holder of record of Company Preferred Stock as of immediately prior to the First Effective Time, an amount equal to the liquidation preference (including all accrued and unpaid dividends as of the First Effective Time) per share as set forth in the Certificate of Designation", "location": "EX-2.1, Section 3.4(b)", "relevance_score": 5}, {"quote": "Each of the parties and the Exchange Agent shall be entitled to deduct and withhold from the Merger Consideration, the amount paid to holders of Company Preferred Stock pursuant to Section 3.4(a) and any amounts otherwise payable pursuant to this Agreement to any Person such amounts as are required to be deducted and withheld under applicable Law related to Taxes.", "location": "EX-2.1, Section 3.3(g)", "relevance_score": 5}], "stock_exchange_ratio_type": [], "st