{"acquirer": [{"quote": "Amazon.com, Inc. (“Amazon”), Grapefruit Acquisition Sub I, Inc., a direct, wholly owned subsidiary of Amazon (“Acquisition Sub I”), Grapefruit Acquisition Sub II, LLC, a direct, wholly owned subsidiary of Amazon (“Acquisition Sub II”), and Globalstar, Inc. (“Globalstar”) entered into an Agreement and Plan of Merger, dated as of April 13, 2026 (as it may be amended from time to time, the “merger agreement”).", "location": "S-4, Questions and Answers About the Mergers, page 1", "relevance_score": 5}, {"quote": "At the effective time of the first merger, you will be entitled to receive, at your election, for each share of Globalstar common stock that you hold, subject to the proration provisions of the merger agreement, and subject to the terms, conditions and procedures set forth in the merger agreement, the following consideration: (i) $90.00 in cash minus the per share adjustment amount (as defined below) (if any), without interest (the “cash consideration”); or (ii) a number of shares of common stock, par value $0.01 per share, of Amazon (the “Amazon common stock”) equal to the exchange ratio described below (which includes an adjustment for the per share adjustment amount (if any)) (the “stock consideration”).", "location": "S-4, Questions and Answers About the Mergers, page 3", "relevance_score": 5}], "target": [{"quote": "The merger agreement contains the terms and conditions of the proposed acquisition of Globalstar by Amazon.", "location": "S-4, Questions and Answers About the Mergers, page 1", "relevance_score": 5}, {"quote": "At the effective time of the first merger, each share of Globalstar common stock (including shares of Globalstar common stock issued for Globalstar warrants immediately prior to the effective time of the first merger (“Globalstar warrant notional common shares”)) issued and outstanding immediately prior to the effective time of the first merger (other than the canceled shares) will, subject to the proration provisions of the merger agreement, be converted into the right to receive, at the election of the applicable Globalstar stockholder with respect to such share, in accordance with, and subject to the terms, conditions and procedures set forth in the merger agreement, the following consideration (collectively with, if applicable, cash in lieu of any fractional shares of Amazon common stock and any dividends or other distributions payable pursuant to the merger agreement): (i) the cash consideration (i.e., $90 in cash minus the per share adjustment amount (if any)), without interest; or (ii) the stock consideration (i.e., a number of validly issued, fully paid and nonassessable shares of Amazon common stock equal to the exchange ratio, as described below (which includes an adjustment for the per share adjustment amount (if any)).", "location": "S-4, Summary—Merger Consideration, page 14", "relevance_score": 5}], "consideration_type": [{"quote": "Each Globalstar stockholder may elect a different form of merger consideration for each share they hold. Accordingly, you may elect to receive (i) solely the cash consideration, (ii) solely the stock consideration, or (iii) if you own more than one share, a combination of the cash consideration for a selected number of shares and the stock consideration for the remaining number of shares.", "location": "S-4, Questions and Answers About the Mergers, page 4", "relevance_score": 5}], "cash_consideration": [{"quote": "for each share of Globalstar common stock and each Globalstar warrant notional common share with respect to which a cash election has been properly made and not properly changed, revoked or deemed revoked pursuant to the merger agreement (a “cash election share”), $90 in cash minus the per share adjustment amount (if any), without interest;", "location": "S-4, The Merger Agreement—Effects of the Mergers, page 96", "relevance_score": 5}, {"quote": "The “Per Share Adjustment Amount” shall mean the quotient of (a) the Adjustment Amount divided by (b) the aggregate number of shares of Company Common Stock to be converted into the right to receive Merger Consideration at the First Effective Time.", "location": "S-4, Annex A—Exhibit A, Definitions, page AA-10", "relevance_score": 4}], "stock_exchange_ratio": [{"quote": "If the Amazon measurement price is less than $280.38, the exchange ratio will equal (x) 0.3210 minus (y) the quotient of the per share adjustment amount (if any) divided by the Amazon measurement price.", "location": "S-4, The Mergers—Merger Consideration, page 39", "relevance_score": 5}, {"quote": "If the Amazon measurement price is equal to or greater than $280.38, the exchange ratio will equal the quotient of (a) (i) $90.00 minus (ii) the per share adjustment amount (if any), divided by (b) the Amazon measurement price.", "location": "S-4, The Mergers—Merger Consideration, page 39", "relevance_score": 5}, {"quote": "for each share of Globalstar common stock and each Globalstar warrant notional common share with respect to which a stock election has been properly made and not properly changed, revoked or deemed revoked pursuant to the merger agreement (a “stock election share”), a number of validly issued, fully paid and nonassessable shares of Amazon common stock equal to the exchange ratio (which includes an adjustment for the per share adjustment amount (if any));", "location": "S-4, The Merger Agreement—Effects of the Mergers, page 96", "relevance_score": 5}], "shareholder_vote_date": [{"quote": "On April 13, 2026, following the execution of the merger agreement, and pursuant to the support agreement, the Supporting Stockholders, which, collectively, on April 13, 2026 owned 74,058,249 shares of Globalstar common stock, representing approximately 57.6% of the aggregate voting power of the 128,598,125 issued and outstanding shares of Globalstar common stock, delivered a written consent in lieu of a meeting of stockholders adopting the merger agreement and approving the transactions contemplated by the merger agreement, including the mergers.", "location": "S-4, The Mergers—No Further Vote Required by Globalstar Stockholders, page 70", "relevance_score": 5}], "closing_conditions": [{"quote": "The respective obligations of each party to effect the mergers are subject to the satisfaction (or waiver by Globalstar and Amazon) of the following conditions:
