{"acquirer": [{"quote": "On April 20, 2026, United Community Banks, Inc., which we refer to as United, and Peach State Bancshares, Inc., which we refer to as Peach State, entered into an Agreement and Plan of Merger, which we refer to as the merger agreement, that provides for the acquisition of Peach State by United.", "location": "S-4/A, Merger Proposed — Your Vote Is Very Important", "relevance_score": 5}, {"quote": "Pursuant to the terms and subject to the conditions set forth in the merger agreement, each issued and outstanding share of Peach State common stock (except for treasury stock or shares owned by Peach State or United, in each case, other than in a fiduciary or agency capacity or as a result of debts previously contracted, and shares held by shareholders who properly exercise appraisal rights) issued and outstanding immediately prior to the effective time of the merger will be converted into the right to receive, at the election of the holder of such share and subject to proration, $31.75 in cash, less any applicable withholding taxes and without interest, or 0.8978 of a share of United common stock.", "location": "S-4/A, Summary — The Merger, page 9", "relevance_score": 5}], "target": [{"quote": "On April 20, 2026, United Community Banks, Inc., which we refer to as United, and Peach State Bancshares, Inc., which we refer to as Peach State, entered into an Agreement and Plan of Merger, which we refer to as the merger agreement, that provides for the acquisition of Peach State by United.", "location": "S-4/A, Merger Proposed — Your Vote Is Very Important", "relevance_score": 5}, {"quote": "Under the merger agreement, Peach State will merge with and into United, with United as the surviving corporation, in a transaction we refer to as the merger.", "location": "S-4/A, Merger Proposed — Your Vote Is Very Important", "relevance_score": 5}], "consideration_type": [{"quote": "Pursuant to the terms and subject to the conditions set forth in the merger agreement, each issued and outstanding share of Peach State common stock (except for treasury stock or shares owned by Peach State or United, in each case, other than in a fiduciary or agency capacity or as a result of debts previously contracted, and shares held by shareholders who properly exercise appraisal rights) issued and outstanding immediately prior to the effective time of the merger will be converted into the right to receive, at the election of the holder of such share and subject to proration, $31.75 in cash, less any applicable withholding taxes and without interest, or 0.8978 of a share of United common stock.", "location": "S-4/A, Summary — The Merger, page 9", "relevance_score": 5}], "cash_consideration": [{"quote": "The “Per Share Cash Consideration” means $31.75.", "location": "S-4/A, Annex A — Merger Agreement, Section 1.5(b)(ii), page A-10", "relevance_score": 5}, {"quote": "for each share of Peach State common stock with respect to which an election to receive cash (referred to as a cash election) has been effectively made and not revoked (referred to as a cash election share), $31.75 in cash (referred to as the cash consideration);", "location": "S-4/A, The Merger Agreement — Merger Consideration, page 59", "relevance_score": 5}], "stock_exchange_ratio": [{"quote": "for each share of Peach State common stock with respect to which an election to receive United common stock (referred to as a stock election) has been effectively made and not revoked (referred to as a stock election share), 0.8978 of a share of United common stock (referred to as the stock consideration); and", "location": "S-4/A, The Merger Agreement — Merger Consideration, page 59", "relevance_score": 5}], "shareholder_vote_date": [{"quote": "The Peach State special meeting will be held on July 21, 2026, at 4:00 P.M., Eastern Time, at Peach State’s main office, located at 121 E.E. Butler Parkway, Gainesville, Georgia 30501.", "location": "S-4/A, Questions and Answers About the Merger, page 5", "relevance_score": 5}, {"quote": "At the special meeting, Peach State shareholders will be asked to consider and vote on:
•
a proposal to adopt and approve the merger agreement, which we refer to as the merger proposal;", "location": "S-4/A, Information About the Peach State Special Meeting — Matters to be Considered at the Meeting, page 27", "relevance_score": 5}], "closing_conditions": [{"quote": "The respective obligations of each of United and Peach State to complete the merger is subject to the satisfaction or waiver of the following conditions:
•
the adoption and approval of the merger agreement by Peach State’s shareholders;
•
the authorization for listing on the NYSE of the United common stock to be issued upon the consummation of the merger, subject to official notice of issuance;
•
the receipt and effectiveness of the requisite regulatory approvals contemplated by the merger agreement and the expiration of all statutory waiting periods in respect thereof, without the imposition of any condition or restriction that would reasonably be expected to have a material adverse effect on the combined company and its subsidiaries, taken as a whole, after giving effect to the merger;
•
the effectiveness of the registration statement of which this proxy statement/prospectus is a part, and the absence of any stop order suspending the effectiveness of such registration statement (or any proceedings for that purpose initiated or threatened by the SEC and not withdrawn);
•
the absence of any order, injunction, or decree by any court or agency of competent jurisdiction or other legal restraint or prohibition preventing the completion of the merger or any of the other transactions contemplated by the merger agreement, and the absence of any law, statute, rule, regulation, order, injunction or decree enacted, entered, promulgated, or enforced by any governmental entity which prohibits or makes illegal consummation of the merger or any of the other transactions contemplated by the merger agreement;
•
the receipt by such party of a written opinion from its respective tax counsel dated as of the closing date of the merger to the effect that the merger will qualify as a “reorganization” within the meaning of Section 368(a) of the Code;
•
the accuracy of the representations and warranties of the other party contained in the merger agreement as of the date of the merger agreement and as of the closing date of the merger, without giving effect to any qualification as to materiality or material adverse effect provided in the merger agreement (with certain exceptions) (and the receipt by such party of an officer’s certificate from the other party to such effect);
•
the performance by the other party in all material respects of all obligations required to be performed by it under the merger agreement at or prior to the closing date of the merger (and the receipt by such party of an officer’s certificate from the other party to such effect); and
•
the absence of any change, state of facts, event, development or effect that has had, or would reasonably be expected to have, either individually or in the aggregate, a material adverse effect on either party since the date of the merger agreement.", "location": "S-4/A, The Merger Agreement — Conditions to Complete the Merger, page 73", "relevance_score": 5}, {"quote": "United’s obligation to complete the merger is further subject to:
•
no more than 5% of the aggregate outstanding shares of Peach State stock having properly notified Peach State of their intent to exercise appraisal rights under applicable law;
•
the receipt of a properly executed FIRPTA certificate from Peach State stating that shares of capital stock of Peach State do not constitute “United States real property interests” under Section 897(c) the Code; and
•
the receipt of evidence of the dissolution of 332 Spring, LLC from Peach State, in form and substance acceptable to United.", "location": "S-4/A, The Merger Agreement — Conditions to Complete the Merger, pages 73–74", "relevance_score": 5}], "event_status": [{"quote": "The merger will be completed only if all conditions to the merger discussed in this proxy statement/​prospectus and set forth in the merger agreement are either satisfied or waived (subject to applicable law).", "location": "S-4/A, The Merger Agreement — Closing and Effective Time of the Merger, page 62", "relevance_score": 5}, {"quote": "The merger cannot be completed unless the merger agreement is adopted and approved by the affirmative vote of a majority of all the votes entitled to be cast thereon by the holders of outstanding shares of Peach State common stock.", "location": "S-4/A, Merger Proposed — Your Vote Is Very Important", "relevance_score": 5}], "security_description": [{"quote": "each share of common stock of the Company, $5.00 par value per share (“Company Common Stock”), issued and outstanding immediately prior to the Effective Time", "location": "S-4/A, Annex A — Merger Agreement, Section 1.5(a), page A-10", "relevance_score": 5}, {"quote": "Peach State is authorized to issue up to 10,000,000 shares of common stock, par value of $5.00 par value, and 2,000,000 shares of preferred stock, no par value.", "location": "S-4/A, Comparison of Shareholders’ Rights — Authorized Capital Stock, page 88", "relevance_score": 5}], "effective_date": [], "available_options": [{"quote": "You may elect to receive either the stock consideration or the cash consideration. However, the ability to receive the merger consideration of your choice will depend on the election of other Peach State shareholders.", "location": "S-4/A, Questions and Answers About the Merger, page 1", "relevance_score": 5}, {"quote": "for each share of Peach State common stock with respect to which an election to receive cash (referred to as a cash election) has been effectively made and not revoked (referred to as a cash election share), $31.75 in cash (referred to as the cash consideration);", "location": "S-4/A, The Merger Agreement — Merger Consideration, page 59", "relevance_score": 5}, {"quote": "for each share of Peach State common stock with respect to which an election to receive United common stock (referred to as a stock election) has been effectively made and not revoked (referred to as a stock election share), 0.8978 of a share of United common stock (referred to as the stock consideration); and", "location": "S-4/A, The Merger Agreement — Merger Consideration, page 59", "relevance_score": 5}], "default_option": [{"quote": "If a Peach State shareholder does not return a properly completed election form by the election deadline specified in the election form, such shareholder’s shares of Peach State common stock will be considered “non-election” shares and will be converted into the right to receive the stock consideration or the cash consideration according to the allocation procedures specified in the merger agreement.", "location": "S-4/A, Questions and Answers About the Merger, page 4", "relevance_score": 5}], "election_deadline": [{"quote": "Unless otherwise agreed in advance by the parties to the merger agreement, election deadline means 5:00 p.m. local time (in the city in which the principal office of the exchange agent is located) on the date which the last business day prior to the Peach State special meeting.", "location": "S-4/A, The Merger Agreement — Election Procedures, page 62", "relevance_score": 5}], "merger_subsidiary": [], "cash_consideration_qualifications": [{"quote": "Pursuant to the terms and subject to the conditions set forth in the merger agreement, each issued and outstanding share of Peach State common stock (except for treasury stock or shares owned by Peach State or United, in each case, other than in a fiduciary or agency capacity or as a result of debts previously contracted, and shares held by shareholders who properly exercise appraisal rights) issued and outstanding immediately prior to the effective time of the merger will be converted into the right to receive, at the election of the holder of such share and subject to proration, $31.75 in cash, less any applicable withholding taxes and without interest, or 0.8978 of a share of United common stock.", "location": "S-4/A, Summary — The Merger, page 9", "relevance_score": 5}, {"quote": "The merger consideration is subject to proration so that 50% of Peach State common stock issued and outstanding immediately prior to the effective time of the merger will be converted into cash consideration and 50% of Peach State common stock will be converted into stock consideration, based on an exchange ratio of 0.8978 of a share of United common stock.", "location": "S-4/A, Summary — The Merger, page 9", "relevance_score": 5}, {"quote": "Cash will be paid in lieu of fractional shares of United common stock as described in the next sentence. Each holder of Peach State common stock that would otherwise have been entitled to receive a fractional share of United common stock in the merger will instead receive a cash payment equal to the product obtained by multiplying (i) the fraction of a share of United common stock to which such holder would otherwise be entitled (accounting for all shares of Peach State common stock held by such holder at the effective time), rounded to the nearest one-thousandth of one share, by (ii) the average closing sale price of United common stock on the twenty (20) consecutive full trading days immediately preceding the closing date as reported on the New York Stock Exchange (“NYSE”).", "location": "S-4/A, The Merger Agreement — No Fractional Shares, page 60", "relevance_score": 5}, {"quote": "If, prior to the Effective Time, the outstanding shares of Parent Common Stock or Company Common Stock shall have been increased, decreased, changed into or exchanged for a different number or kind of shares or securities as a result of a reorganization, recapitalization, reclassification, stock dividend, stock split, reverse stock split or other similar change in capitalization, or there shall be any extraordinary dividend or distribution, an appropriate and proportionate adjustment shall be made to each of the Per Share Cash Consideration and the Exchange Ratio to give holders of Company Common Stock the same economic effect as contemplated by this Agreement prior to such event;", "location": "S-4/A, Annex A — Merger Agreement, Section 1.5(c), page A-11", "relevance_score": 5}], "stock_exchange_ratio_type": [{"quote": "Although the exchange ratio is fixed, the value of the stock consideration will fluctuate between the date of this proxy statement/prospectus and the completion of the merger based upon the market value of United common stock.", "location": "S-4/A, Questions and Answers About the Merger, page 3", "relevance_score": 5}], "stock_exchange_ratio_qualifications": [{"quote": "The merger consideration is subject to proration so that 50% of Peach State common stock issued and outstanding immediately prior to the effective time of the merger will be converted into cash consideration and 50% of Peach State common stock will be converted into stock consideration, based on an exchange ratio of 0.8978 of a share of United common stock.", "location": "S-4/A, Summary — The Merger, page 9", "relevance_score": 5}, {"quote": "If, prior to the Effective Time, the outstanding shares of Parent Common Stock or Company Common Stock shall have been increased, decreased, changed into or exchanged for a different number or kind of shares or securities as a result of a reorganization, recapitalization, reclassification, stock dividend, stock split, reverse stock split or other similar change in capitalization, or there shall be any extraordinary dividend or distribution, an appropriate and proportionate adjustment shall be made to each of the Per Share Cash Consideration and the Exchange Ratio to give holders of Company Common Stock the same economic effect as contemplated by this Agreement prior to such event;", "location": "S-4/A, Annex A — Merger Agreement, Section 1.5(c), page A-11", "relevance_score": 5}, {"quote": "No fractional shares of United common stock will be issued in the merger, and holders of Peach State common stock will be entitled to receive cash in lieu of fractional shares.", "location": "S-4/A, Summary — The Merger, page 9", "relevance_score": 5}], "other_consideration": [], "expected_closing": [{"quote": "United and Peach State expect to complete the merger in the third quarter of 2026. However, neither United nor Peach State can assure you of when or if the merger will be completed.", "location": "S-4/A, Questions and Answers About the Merger, page 7", "relevance_score": 5}], "event_status_details": [{"quote": "The merger agreement was executed by Peach State and United on April 20, 2026, and the transaction was publicly announced prior to the opening of the financial markets on April 21, 2026.", "location": "S-4/A, The Merger — Background of the Merger, page 39", "relevance_score": 5}, {"quote": "Peach State must obtain the approval of the merger agreement by the Peach State shareholders at the Peach State special meeting, and United must obtain necessary regulatory approvals. In addition, each party is required to satisfy certain other customary closing conditions.", "location": "S-4/A, Questions and Answers About the Merger, pages 7–8", "relevance_score": 5}], "agreement_name": [{"quote": "On April 20, 2026, United Community Banks, Inc., which we refer to as United, and Peach State Bancshares, Inc., which we refer to as Peach State, entered into an Agreement and Plan of Merger, which we refer to as the merger agreement, that provides for the acquisition of Peach State by United.", "location": "S-4/A, Merger Proposed — Your Vote Is Very Important", "relevance_score": 5}], "agreement_date": [{"quote": "THIS AGREEMENT AND PLAN OF MERGER (this “Agreement”), dated as of April 20, 2026, is entered into by and between United Community Banks, Inc., a Georgia corporation (“Parent”), and Peach State Bancshares, Inc., a Georgia corporation (the “Company”).", "location": "S-4/A, Annex A — Agreement and Plan of Merger, page A-9", "relevance_score": 5}], "original_filing_date": [], "related_entities": [], "security_identifiers": []}

