{"acquirer": [{"quote": "each share of common stock, par value $0.0001 per share, of Globalstar (“Globalstar common stock”) issued and outstanding immediately prior to the effective time of the first merger (other than shares of Globalstar common stock held, directly or indirectly, by Globalstar or any of its subsidiaries or by Amazon, Acquisition Sub I, Acquisition Sub II or any of their respective wholly owned subsidiaries (the “canceled shares”)) will, subject to the proration provisions of the merger agreement, be converted into the right to receive, at the election of the applicable Globalstar stockholder (as defined below) with respect to such share, in accordance with, and subject to the terms, conditions and procedures set forth in the merger agreement, the following consideration: (i) $90.00 in cash minus the per share adjustment amount (as defined below) (if any), without interest (the “cash consideration”); or (ii) a number of shares of common stock, par value $0.01 per share, of Amazon (the “Amazon common stock”) equal to the exchange ratio described below (which includes an adjustment for the per share adjustment amount (if any)) (the “stock consideration”).", "location": "S-4/A, INFORMATION STATEMENT/PROSPECTUS AND NOTICE OF ACTION BY WRITTEN CONSENT", "relevance_score": 5}, {"quote": "Amazon.com, Inc. (“Amazon”), Grapefruit Acquisition Sub I, Inc., a direct, wholly owned subsidiary of Amazon (“Acquisition Sub I”), Grapefruit Acquisition Sub II, LLC, a direct, wholly owned subsidiary of Amazon (“Acquisition Sub II”), and Globalstar, Inc. (“Globalstar”) entered into an Agreement and Plan of Merger, dated as of April 13, 2026 (as it may be amended from time to time, the “merger agreement”).", "location": "S-4/A, QUESTIONS AND ANSWERS ABOUT THE MERGERS, page 1", "relevance_score": 5}], "target": [{"quote": "Amazon.com, Inc. (“Amazon”), Grapefruit Acquisition Sub I, Inc., a direct, wholly owned subsidiary of Amazon (“Acquisition Sub I”), Grapefruit Acquisition Sub II, LLC, a direct, wholly owned subsidiary of Amazon (“Acquisition Sub II”), and Globalstar, Inc. (“Globalstar”) entered into an Agreement and Plan of Merger, dated as of April 13, 2026 (as it may be amended from time to time, the “merger agreement”).", "location": "S-4/A, QUESTIONS AND ANSWERS ABOUT THE MERGERS, page 1", "relevance_score": 5}, {"quote": "As a result of the first merger, Globalstar will become a direct, wholly owned subsidiary of Amazon and will no longer be a publicly held company.", "location": "S-4/A, QUESTIONS AND ANSWERS ABOUT THE MERGERS, page 1", "relevance_score": 5}], "consideration_type": [{"quote": "You may elect to receive (i) solely the cash consideration, (ii) solely the stock consideration, or (iii) if you own more than one share, a combination of the cash consideration for a selected number of shares and the stock consideration for the remaining number of shares.", "location": "S-4/A, INFORMATION STATEMENT/PROSPECTUS AND NOTICE OF ACTION BY WRITTEN CONSENT", "relevance_score": 5}], "cash_consideration": [{"quote": "for each share of Globalstar common stock and each Globalstar warrant notional common share with respect to which a cash election has been properly made and not properly changed, revoked or deemed revoked pursuant to the merger agreement (a “cash election share”), $90 in cash minus the per share adjustment amount (if any), without interest;", "location": "S-4/A, THE MERGER AGREEMENT — Effects of the Mergers, page 96", "relevance_score": 5}], "stock_exchange_ratio": [{"quote": "If the Amazon measurement price is less than $280.38, the exchange ratio will equal (x) 0.3210 minus (y) the quotient of the per share adjustment amount (if any) divided by the Amazon measurement price.", "location": "S-4/A, THE MERGERS — Merger Consideration, page 39", "relevance_score": 5}, {"quote": "If the Amazon measurement price is equal to or greater than $280.38, the exchange ratio will equal the quotient of (a) (i) $90.00 minus (ii) the per share adjustment amount (if any), divided by (b) the Amazon measurement price.", "location": "S-4/A, THE MERGERS — Merger Consideration, page 39", "relevance_score": 5}, {"quote": "the stock consideration (i.e., a number of validly issued, fully paid and nonassessable shares of Amazon common stock equal to the exchange ratio (which includes an adjustment for the per share adjustment amount (if any))).", "location": "S-4/A, THE MERGERS — Merger Consideration, page 39", "relevance_score": 5}], "shareholder_vote_date": [{"quote": "On April 13, 2026, following the execution of the merger agreement, and pursuant to the support agreement, the Supporting Stockholders, which, collectively, on April 13, 2026 owned 74,058,249 shares of Globalstar common stock, representing approximately 57.6% of the aggregate voting power of the 128,598,125 issued and outstanding shares of Globalstar common stock as of such date, delivered a written consent in lieu of a meeting of stockholders adopting the merger agreement and approving the transactions contemplated by the merger agreement, including the mergers.", "location": "S-4/A, THE MERGERS — No Further Vote Required by Globalstar Stockholders, page 70", "relevance_score": 5}], "closing_conditions": [{"quote": "The respective obligations of each party hereto to consummate the Mergers are subject to the satisfaction or waiver by the Company and Parent at or prior to the First Effective Time of the following conditions:", "location": "S-4/A, Annex A — ARTICLE VII, Section 7.1, page A-58", "relevance_score": 5}, {"quote": "(a) the Requisite Stockholder Approval shall have been obtained;
(b) any waiting period (or any extension thereof) applicable to the consummation of the Mergers under the HSR Act shall have expired or early termination thereof shall have been granted;
(c) the Registration Statement shall have become effective under the Securities Act, no stop order suspending the effectiveness of the Registration Statement shall have been issued by the SEC and remain in effect and no proceeding for that purpose shall have been initiated by the SEC with respect to the Registration Statement that has not been withdrawn;
(d) any Governmental Authorization required to be obtained prior to consummation of the Mergers in connection with the Mergers set forth in Section 7.1(d) of the Company Disclosure Letter (the “Required Governmental Authorizations”) shall have been obtained (in accordance with Section 7.1(d) of the Company Disclosure Letter) and shall remain in full force and effect;
(e) at least twenty (20) calendar days shall have elapsed since the Company mailed to the stockholders of the Company the Information Statement as contemplated by Regulation 14C of the Exchange Act (including Rule 14c-2 promulgated under the Exchange Act); and
(f) no Governmental Authority of competent jurisdiction shall have enacted, issued, promulgated, enforced or entered any Law or Order which is then in effect and has the effect of preventing, making illegal or enjoining the consummation of the Mergers.", "location": "S-4/A, Annex A — ARTICLE VII, Section 7.1, page A-58", "relevance_score": 5}, {"quote": "The obligations of each party to complete the mergers are also subject to the satisfaction or waiver of other conditions, including:
•
the accuracy of the representations and warranties of the other party under the merger agreement (subject to the materiality standards set forth in the merger agreement);
•
the performance or compliance by the other party of its respective obligations under the merger agreement in all material respects;
•
there not having occurred any material adverse effect (as defined in the section titled “The Merger Agreement — Material Adverse Effect”) with respect to the other party since April 13, 2026; and
•
the delivery of an officer’s certificate by the other party certifying satisfaction of the three preceding conditions (and, in the case of Globalstar, the satisfaction of the conditions described in the following paragraph).", "location": "S-4/A, SUMMARY — Conditions to Completion of the Mergers, page 22", "relevance_score": 5}, {"quote": "In addition, Amazon’s obligation to consummate the mergers is subject to the satisfaction or waiver of Globalstar’s receipt of certain governmental authorizations related to the C-3 system and their continuance in full force and effect and the achievement by Globalstar of certain milestones relating to the launch and operation of HIBLEO-4 replacement satellites.", "location": "S-4/A, SUMMARY — Conditions to Completion of the Mergers, page 22", "relevance_score": 5}], "event_status": [{"quote": "Amazon and Globalstar currently expect the mergers to be completed in 2027, subject to the satisfaction or waiver of the closing conditions contained in the merger agreement. However, Amazon and Globalstar cannot predict the actual date on which the mergers will be completed because completion is subject to conditions beyond their control, and it is possible that such conditions could result in the mergers being completed earlier or later than expected or not being completed at all.", "location": "S-4/A, QUESTIONS AND ANSWERS ABOUT THE MERGERS, page 11", "relevance_score": 5}], "security_description": [{"quote": "Upon completion of the first merger, each share of Globalstar common stock (including Globalstar warrant notional common shares) issued and outstanding immediately prior to the effective time of the first merger (other than the canceled shares) will be converted into the right to receive, at the election of the applicable Globalstar stockholder (as defined below) with respect to such share, (i) the cash consideration (i.e., $90 per share in cash minus the per share adjustment amount (if any), without interest), subject to proration; or (ii) the stock consideration (i.e., a number of validly issued, fully paid and nonassessable shares of Amazon common stock equal to the exchange ratio (which includes an adjustment for the per share adjustment amount (if any))).", "location": "S-4/A, THE MERGERS — Merger Consideration, page 39", "relevance_score": 5}], "effective_date": [], "available_options": [{"quote": "Each Globalstar stockholder may elect a different form of consideration for each share that such Globalstar stockholder owns. Globalstar stockholders may elect to receive (i) solely the cash consideration, (ii) solely the stock consideration, or (iii) if a Globalstar stockholder owns more than one share, a combination of the cash consideration for a selected number of shares and the stock consideration for the remaining number of shares.", "location": "S-4/A, THE MERGERS — Merger Consideration, page 40", "relevance_score": 5}, {"quote": "Upon completion of the first merger, each share of Globalstar common stock (including Globalstar warrant notional common shares) issued and outstanding immediately prior to the effective time of the first merger (other than the canceled shares) will be converted into the right to receive, at the election of the applicable Globalstar stockholder (as defined below) with respect to such share, (i) the cash consideration (i.e., $90 per share in cash minus the per share adjustment amount (if any), without interest), subject to proration; or (ii) the stock consideration (i.e., a number of validly issued, fully paid and nonassessable shares of Amazon common stock equal to the exchange ratio (which includes an adjustment for the per share adjustment amount (if any))).", "location": "S-4/A, THE MERGERS — Merger Consideration, page 39", "relevance_score": 5}], "default_option": [{"quote": "Globalstar stockholders who do not make a valid and timely election will be treated as having elected to receive the stock consideration.", "location": "S-4/A, THE MERGERS — Merger Consideration, page 40", "relevance_score": 5}], "election_deadline": [{"quote": "The election deadline is expected to be 5:00 p.m. (New York City time) on the date that is three (3) business days prior to the anticipated closing date, or such other date and time as may be mutually agreed to by Amazon and Globalstar.", "location": "S-4/A, QUESTIONS AND ANSWERS ABOUT THE MERGERS, page 7", "relevance_score": 5}], "merger_subsidiary": [{"quote": "Grapefruit Acquisition Sub I, Inc., a direct, wholly owned subsidiary of Amazon (“Acquisition Sub I”), Grapefruit Acquisition Sub II, LLC, a direct, wholly owned subsidiary of Amazon (“Acquisition Sub II”)", "location": "S-4/A, QUESTIONS AND ANSWERS ABOUT THE MERGERS, page 1", "relevance_score": 5}], "cash_consideration_qualifications": [{"quote": "If the Customer payment is payable by Globalstar under the letter agreement, then pursuant to the merger agreement, the aggregate merger consideration that Globalstar stockholders will receive will be adjusted downwards by an amount equal to the quotient of (a) the amount of the Customer payment (if any), divided by (b) the aggregate number of shares of Globalstar common stock to be converted into the right to receive the merger consideration (the “per share adjustment amount”), as follows: (i) in the case of shares of Globalstar common stock that are converted into the right to receive the cash consideration, a reduction of the amount of cash paid in respect of each share by the per share adjustment amount, and (ii) in the case of shares of Globalstar common stock that are converted into the right to receive the stock consideration, a reduction in the number of shares of Amazon common stock paid in respect of each share with a value equal to the per share adjustment amount.", "location": "S-4/A, QUESTIONS AND ANSWERS ABOUT THE MERGERS, pages 3–4", "relevance_score": 5}, {"quote": "The merger agreement provides that the total number of shares of Globalstar common stock that will be entitled to receive the cash consideration will not exceed the maximum cash share number (i.e., forty percent (40%) of the aggregate number of shares of Globalstar common stock issued and outstanding immediately prior to the effective time of the first merger (other than canceled shares)). If the cash election is oversubscribed, each Globalstar stockholder making a valid cash election will receive a pro rata portion of the available cash consideration in cash and the remaining portion in shares of Amazon common stock at the exchange ratio.", "location": "S-4/A, THE MERGERS — Merger Consideration, page 40", "relevance_score": 5}, {"quote": "for each share of Globalstar common stock and each Globalstar warrant notional common share with respect to which a cash election has been properly made and not properly changed, revoked or deemed revoked pursuant to the merger agreement (a “cash election share”), $90 in cash minus the per share adjustment amount (if any), without interest;", "location": "S-4/A, THE MERGER AGREEMENT — Effects of the Mergers, page 96", "relevance_score": 5}, {"quote": "Each party to the merger agreement and the exchange agent will be entitled to deduct and withhold from the merger consideration, the amount paid to holders of Globalstar preferred shares, and any amounts otherwise payable pursuant to the merger agreement to any person, such amounts as are required to be deducted and withheld under the Code or any other applicable tax law.", "location": "S-4/A, THE MERGER AGREEMENT — Withholding Rights, page 102", "relevance_score": 5}, {"quote": "No fractional shares of Amazon common stock will be issued in the mergers, and Globalstar stockholders who receive the stock consideration will instead receive cash in lieu of fractional shares of Amazon common stock.", "location": "S-4/A, THE MERGERS — Merger Consideration, page 40", "relevance_score": 5}], "stock_exchange_ratio_type": [{"quote": "The exchange ratio for the stock consideration will be determined based on the Amazon measurement price (i.e., the volume weighted average price, rounded to four decimal places, of Amazon common stock over the twenty (20) consecutive trading day period ending on (and including) the second trading day immediately prior to the closing date).", "location": "S-4/A, THE MERGERS — Merger Consideration, page 39", "relevance_score": 5}, {"quote": "If the Amazon measurement price is less than $280.38, the exchange ratio will equal (x) 0.3210 minus (y) the quotient of the per share adjustment amount (if any) divided by the Amazon measurement price.", "location": "S-4/A, THE MERGERS — Merger Consideration, page 39", "relevance_score": 5}, {"quote": "If the Amazon measurement price is equal to or greater than $280.38, the exchange ratio will equal the quotient of (a) (i) $90.00 minus (ii) the per share adjustment amount (if any), divided by (b) the Amazon measurement price.", "location": "S-4/A, THE MERGERS — Merger Consideration, page 39", "relevance_score": 5}], "stock_exchange_ratio_qualifications": [{"quote": "The exchange ratio for the stock consideration will be determined based on the Amazon measurement price (i.e., the volume weighted average price, rounded to four decimal places, of Amazon common stock over the twenty (20) consecutive trading day period ending on (and including) the second trading day immediately prior to the closing date).", "location": "S-4/A, THE MERGERS — Merger Consideration, page 39", "relevance_score": 5}, {"quote": "If the Amazon measurement price is less than $280.38, the exchange ratio will equal (x) 0.3210 minus (y) the quotient of the per share adjustment amount (if any) divided by the Amazon measurement price.", "location": "S-4/A, THE MERGERS — Merger Consideration, page 39", "relevance_score": 5}, {"quote": "If the Amazon measurement price is equal to or greater than $280.38, the exchange ratio will equal the quotient of (a) (i) $90.00 minus (ii) the per share adjustment amount (if any), divided by (b) the Amazon measurement price.", "location": "S-4/A, THE MERGERS — Merger Consideration, page 39", "relevance_score": 5}, {"quote": "The implied value of the stock consideration will change as the market price of Amazon common stock changes, but will be capped at $90.00 per share (not accounting for any adjustment for the per share adjustment amount (if any)).", "location": "S-4/A, THE MERGERS — Merger Consideration, page 40", "relevance_score": 5}, {"quote": "No fractional shares of Amazon common stock will be issued in the mergers, and Globalstar stockholders who receive the stock consideration will instead receive cash in lieu of fractional shares of Amazon common stock.", "location": "S-4/A, THE MERGERS — Merger Consideration, page 40", "relevance_score": 5}, {"quote": "Accordingly, in order to ensure that the mergers qualify as a reorganization within the meaning of Section 368(a) of the Code, the parties have agreed that the exchange ratio shall be increased to the minimum extent necessary to cause the mergers to satisfy the “continuity of interest” requirement set forth in Treasury Regulations Section 1.368-1(e).", "location": "S-4/A, THE MERGER AGREEMENT — Tax Related Adjustments, page 98", "relevance_score": 5}], "other_consideration": [], "expected_closing": [{"quote": "Amazon and Globalstar currently expect the mergers to be completed in 2027, subject to the satisfaction or waiver of the closing conditions contained in the merger agreement.", "location": "S-4/A, QUESTIONS AND ANSWERS ABOUT THE MERGERS, page 11", "relevance_score": 5}], "event_status_details": [{"quote": "On April 13, 2026, following the execution of the merger agreement, and pursuant to the support agreement, the Supporting Stockholders, which, collectively, on April 13, 2026 owned 74,058,249 shares of Globalstar common stock, representing approximately 57.6% of the aggregate voting power of the 128,598,125 issued and outstanding shares of Globalstar common stock as of such date, delivered a written consent in lieu of a meeting of stockholders adopting the merger agreement and approving the transactions contemplated by the merger agreement, including the mergers.", "location": "S-4/A, THE MERGERS — No Further Vote Required by Globalstar Stockholders, page 70", "relevance_score": 5}, {"quote": "Amazon and Globalstar currently expect the mergers to be completed in 2027, subject to the satisfaction or waiver of the closing conditions contained in the merger agreement.", "location": "S-4/A, QUESTIONS AND ANSWERS ABOUT THE MERGERS, page 11", "relevance_score": 5}], "agreement_name": [{"quote": "Amazon.com, Inc. (“Amazon”), Grapefruit Acquisition Sub I, Inc., a direct, wholly owned subsidiary of Amazon (“Acquisition Sub I”), Grapefruit Acquisition Sub II, LLC, a direct, wholly owned subsidiary of Amazon (“Acquisition Sub II”), and Globalstar, Inc. (“Globalstar”) entered into an Agreement and Plan of Merger, dated as of April 13, 2026 (as it may be amended from time to time, the “merger agreement”).", "location": "S-4/A, QUESTIONS AND ANSWERS ABOUT THE MERGERS, page 1", "relevance_score": 5}], "agreement_date": [{"quote": "Amazon.com, Inc. (“Amazon”), Grapefruit Acquisition Sub I, Inc., a direct, wholly owned subsidiary of Amazon (“Acquisition Sub I”), Grapefruit Acquisition Sub II, LLC, a direct, wholly owned subsidiary of Amazon (“Acquisition Sub II”), and Globalstar, Inc. (“Globalstar”) entered into an Agreement and Plan of Merger, dated as of April 13, 2026 (as it may be amended from time to time, the “merger agreement”).", "location": "S-4/A, QUESTIONS AND ANSWERS ABOUT THE MERGERS, page 1", "relevance_score": 5}], "original_filing_date": [{"quote": "In connection with the registration statement on Form S-4, including the information statement/prospectus forming a part thereof, filed with the Securities and Exchange Commission (the “SEC”) on July 31, 2026 (File No. 333-297911), as amended or supplemented through the date hereof (the “Registration