{"acquirer": [{"quote": "THIS AGREEMENT AND PLAN OF MERGER, dated as of April 13, 2026 (this “Agreement”), is made by and among Amazon.com, Inc., a Delaware corporation (“Parent”), Grapefruit Acquisition Sub I, Inc., a Delaware corporation and a direct wholly owned Subsidiary of Parent (“Acquisition Sub I”), Grapefruit Acquisition Sub II, LLC, a Delaware limited liability company and a direct wholly owned Subsidiary of Parent (“Acquisition Sub II”), and Globalstar, Inc., a Delaware corporation (the “Company”).", "location": "S-4/A, Annex A — Agreement and Plan of Merger, page A-1", "relevance_score": 5}, {"quote": "Immediately following the First Effective Time, the Surviving Corporation shall pay, in cash, to each holder of record of Company Preferred Stock as of immediately prior to the First Effective Time, an amount equal to the liquidation preference (including all accrued and unpaid dividends as of the First Effective Time) per share as set forth in the Certificate of Designation, in full satisfaction of all rights of such holder with respect to such shares of Company Preferred Stock.", "location": "S-4/A, Annex A — ARTICLE III, Section 3.4(b), page A-11", "relevance_score": 5}], "target": [{"quote": "THIS AGREEMENT AND PLAN OF MERGER, dated as of April 13, 2026 (this “Agreement”), is made by and among Amazon.com, Inc., a Delaware corporation (“Parent”), Grapefruit Acquisition Sub I, Inc., a Delaware corporation and a direct wholly owned Subsidiary of Parent (“Acquisition Sub I”), Grapefruit Acquisition Sub II, LLC, a Delaware limited liability company and a direct wholly owned Subsidiary of Parent (“Acquisition Sub II”), and Globalstar, Inc., a Delaware corporation (the “Company”).", "location": "S-4/A, Annex A — Agreement and Plan of Merger, page A-1", "relevance_score": 5}, {"quote": "Immediately upon receipt by each holder of its liquidating distribution, all shares of Company Preferred Stock owned by such holder shall be canceled and shall cease to exist, and such holder of Company Preferred Stock will not be entitled to any other amounts from the Surviving Corporation or Parent.", "location": "S-4/A, Annex A — ARTICLE III, Section 3.4(b), page A-11", "relevance_score": 5}], "consideration_type": [{"quote": "In accordance with Globalstar’s Certificate of Designation, at the effective time of the first merger, each share of Globalstar preferred stock outstanding will be automatically converted into the right to receive a liquidating distribution in the initial amount of the liquidation preference of $1,000 per share in cash plus any unpaid accrued dividends on such share.", "location": "S-4/A, THE MERGER AGREEMENT — Treatment of Globalstar Preferred Stock, page 103", "relevance_score": 5}], "cash_consideration": [{"quote": "In accordance with Globalstar’s Certificate of Designation, at the effective time of the first merger, each share of Globalstar preferred stock outstanding will be automatically converted into the right to receive a liquidating distribution in the initial amount of the liquidation preference of $1,000 per share in cash plus any unpaid accrued dividends on such share.", "location": "S-4/A, THE MERGER AGREEMENT — Treatment of Globalstar Preferred Stock, page 103", "relevance_score": 5}], "stock_exchange_ratio": [{"quote": "Immediately upon receipt by each holder of its liquidating distribution, all shares of Company Preferred Stock owned by such holder shall be canceled and shall cease to exist, and such holder of Company Preferred Stock will not be entitled to any other amounts from the Surviving Corporation or Parent.", "location": "S-4/A, Annex A — ARTICLE III, Section 3.4(b), page A-11", "relevance_score": 5}], "shareholder_vote_date": [], "closing_conditions": [{"quote": "The respective obligations of each party hereto to consummate the Mergers are subject to the satisfaction or waiver by the Company and Parent at or prior to the First Effective Time of the following conditions:", "location": "S-4/A, Annex A — ARTICLE VII, Section 7.1, page A-58", "relevance_score": 5}, {"quote": "(a) the Requisite Stockholder Approval shall have been obtained;
(b) any waiting period (or any extension thereof) applicable to the consummation of the Mergers under the HSR Act shall have expired or early termination thereof shall have been granted;
(c) the Registration Statement shall have become effective under the Securities Act, no stop order suspending the effectiveness of the Registration Statement shall have been issued by the SEC and remain in effect and no proceeding for that purpose shall have been initiated by the SEC with respect to the Registration Statement that has not been withdrawn;
(d) any Governmental Authorization required to be obtained prior to consummation of the Mergers in connection with the Mergers set forth in Section 7.1(d) of the Company Disclosure Letter (the “Required Governmental Authorizations”) shall have been obtained (in accordance with Section 7.1(d) of the Company Disclosure Letter) and shall remain in full force and effect;
(e) at least twenty (20) calendar days shall have elapsed since the Company mailed to the stockholders of the Company the Information Statement as contemplated by Regulation 14C of the Exchange Act (including Rule 14c-2 promulgated under the Exchange Act); and
(f) no Governmental Authority of competent jurisdiction shall have enacted, issued, promulgated, enforced or entered any Law or Order which is then in effect and has the effect of preventing, making illegal or enjoining the consummation of the Mergers.", "location": "S-4/A, Annex A — ARTICLE VII, Section 7.1, page A-58", "relevance_score": 5}, {"quote": "The obligations of each party to complete the mergers are also subject to the satisfaction or waiver of other conditions, including:
