ocation": "S-4, Annex A — Business Combination Agreement, Section 1.17, page A-9", "relevance_score": 5}], "other_consideration": [], "expected_closing": [{"quote": "It is currently expected that the Business Combination will be consummated in the second quarter of 2026.", "location": "S-4, Questions and Answers About the Business Combination, page xxviii", "relevance_score": 5}], "event_status_details": [{"quote": "On November 26, 2025, FACT entered into the Business Combination Agreement with Sponsor HoldCo, Merger Sub and PAD.", "location": "S-4, Proposal No. 1 — The Business Combination Proposal — Structure of the Business Combination, page 64", "relevance_score": 5}, {"quote": "The completion of the Business Combination is subject to a number of conditions, including those in the Business Combination Agreement. The timing and completion of the Business Combination is not assured", "location": "S-4, Risk Factors, page 37", "relevance_score": 5}], "agreement_name": [{"quote": "the Business Combination Agreement, dated as of November 26, 2025, by and among FACT, FACT II Acquisition LLC, a Cayman Islands limited liability company (“Sponsor HoldCo”), Patriot Merger Subsidiary, Inc., a Florida corporation and wholly-owned subsidiary of FACT (“Merger Sub”), and Precision Aerospace & Defense Group, Inc., a Florida corporation (“PAD”)", "location": "S-4, preliminary proxy statement/prospectus", "relevance_score": 5}], "agreement_date": [{"quote": "the Business Combination Agreement, dated as of November 26, 2025, by and among FACT, FACT II Acquisition LLC, a Cayman Islands limited liability company (“Sponsor HoldCo”), Patriot Merger Subsidiary, Inc., a Florida corporation and wholly-owned subsidiary of FACT (“Merger Sub”), and Precision Aerospace & Defense Group, Inc., a Florida corporation (“PAD”)", "location": "S-4, preliminary proxy statement/prospectus", "relevance_score": 5}], "original_filing_date": [], "related_entities": [{"quote": "Sponsor HoldCo was formed prior to the IPO for the purpose of acting as the sponsor of FACT. It is responsible for organizing, directing, and managing the business and affairs of FACT from its incorporation, through the consummation of the IPO, the negotiation of the Business Combination Agreement, until the consummation of the Business Combination.", "location": "S-4, Questions and Answers About the Business Combination, page xxi", "relevance_score": 5}, {"quote": "“Sponsor HoldCo” means FACT II Acquisition LLC, a Cayman Islands limited liability company.", "location": "S-4, Frequently Used Terms, page vii", "relevance_score": 3}], "security_identifiers": []}

{"acquirer": [{"quote": "Trailblazer Holdings, Inc., a Delaware corporation and a direct, wholly owned subsidiary of Trailblazer (“Holdings”)", "location": "S-4/A, preliminary proxy statement/prospectus", "relevance_score": 5}, {"quote": "Each share of Cyabra Ordinary Shares issued and outstanding immediately prior to the Effective Time shall, in accordance with Cyabra’s Amended and Restated Articles of Association (the “Articles of Association”), be converted into the right to receive a number of shares of Holdings Common Stock equal to the Conversion Ratio.", "location": "S-4/A, Summary of the Proxy Statement/Prospectus — Merger Consideration, page 21", "relevance_score": 5}], "target": [{"quote": "Cyabra Strategy Ltd., a private company organized in Israel (“Cyabra”)", "location": "S-4/A, preliminary proxy statement/prospectus", "relevance_score": 5}, {"quote": "Merger Sub shall merge with and into Cyabra, with Cyabra being the surviving entity", "location": "S-4/A, preliminary proxy statement/prospectus", "relevance_score": 5}], "consideration_type": [{"quote": "Each share of Cyabra Ordinary Shares issued and outstanding immediately prior to the Effective Time shall, in accordance with Cyabra’s Amended and Restated Articles of Association (the “Articles of Association”), be converted into the right to receive a number of shares of Holdings Common Stock equal to the Conversion Ratio.", "location": "S-4/A, Summary of the Proxy Statement/Prospectus — Merger Consideration, page 21", "relevance_score": 5}], "cash_consideration": [], "stock_exchange_ratio": [{"quote": "Each share of Cyabra Ordinary Shares issued and outstanding immediately prior to the Effective Time shall, in accordance with Cyabra’s Amended and Restated Articles of Association (the “Articles of Association”), be converted into the right to receive a number of shares of Holdings Common Stock equal to the Conversion Ratio.", "location": "S-4/A, Summary of the Proxy Statement/Prospectus — Merger Consideration, page 21", "relevance_score": 5}, {"quote": "“Conversion Ratio” means the ratio (rounded down to four decimal places), equal to the quotient obtained by dividing (a) 10,600,000 shares of Holdings Common Stock constituting the Aggregate Merger Consideration by (b) Cyabra’s outstanding shares, on a fully-diluted basis.", "location": "S-4/A, Frequently Used Terms, page 2", "relevance_score": 5}], "shareholder_vote_date": [], "closing_conditions": [{"quote": "The Closing is subject to certain customary conditions, including, among other things: (a) no law or order shall restrain or prohibit the Business Combination; (b) any applicable waiting periods under the Hart-Scott Rodino Antitrust Improvements Act of 1976, as amended (the “HSR Act”), with respect to the Business Combination shall have expired or been terminated; (c) all matters requiring approval of Cyabra’s shareholders shall have been obtained; (d) all matters require approval of Trailblazer’s stockholders shall have been obtained; (e) the shares comprising the Aggregate Merger Consideration being conditionally approved for listing on Nasdaq; (f) the effectiveness of the registration statement of which this proxy statement/prospectus forms a part; (g) at least fifty (50) days shall have elapsed after the filing of the merger proposal with the Israeli Registrar of Companies and at least thirty (30) days shall have elapsed after Cyabra received the required shareholder approvals; (h) Cyabra shall have delivered to Trailblazer a certificate conforming to the requirements of Treasury Regulation Sections 1.897-2(h)(1)(i) and 1.1445-2(c)(3)(i) and a notice under Treasury Regulation Section 1.897-2(h)(2) to be delivered to the IRS as required under the applicable Treasury Regulations; (i) Cyabra shall have obtained each consent listed on the applicable section of the Disclosure Schedules to the Merger Agreement, (j) an exemption from filing an Israeli prospectus with the Israeli Securities Authority shall have been obtained; (k) the size and composition of the Combined Company Board shall have been appointed as set forth in the Merger Agreement; (l) the PIPE Investment (as defined below) shall have been consummated; (m) the financing of the 2024 Convertible Notes (as defined below) shall have been consummated and (n) the Tax Rulings (or Interim Tax Rulings) (each as defined in the Merger Agreement) shall have been obtained.", "location": "S-4/A, Summary of the Proxy Statement/Prospectus — Conditions to Closing, page 23", "relevance_score": 5}, {"quote": "Each party’s obligation to consummate the Business Combination is also subject to other specified customary conditions, including regarding the accuracy of the representations and warranties of the other party, subject to the applicable materiality standard, and the performance in all material respects by the other party of its obligations under the Merger Agreement required to be performed on or prior to the date of the closing of the Business Combination.", "location": "S-4/A, Summary of the Proxy Statement/Prospectus — Conditions to Closing, page 23", "relevance_score": 5}, {"quote": "The approval of the Merger Proposal, the Charter Amendment Proposal, the First Nasdaq Proposal and the Incentive Plan Proposal are preconditions to the consummation of the Business Combination.", "location": "S-4/A, Notice of Special Meeting of Stockholders", "relevance_score": 5}], "event_status": [{"quote": "On November 6, 2025, the parties thereto amended the Merger Agreement to, among other things:", "location": "S-4/A, Summary of the Proxy Statement/Prospectus — Amendments to the Merger Agreement, page 24", "relevance_score": 5}], "security_description": [{"quote": "“Cyabra Ordinary Shares” mean the ordinary shares of Cyabra, NIS 0.01 par value per share other than the LifeSci Ordinary Shares, the Lowenstein Ordinary Shares and the Loeb Ordinary Shares.", "location": "S-4/A, Frequently Used Terms, page 2", "relevance_score": 5}], "effective_date": [], "available_options": [{"quote": "Each share of Cyabra Ordinary Shares issued and outstanding immediately prior to the Effective Time shall, in accordance with Cyabra’s Amended and Restated Articles of Association (the “Articles of Association”), be converted into the right to receive a number of shares of Holdings Common Stock equal to the Conversion Ratio.", "location": "S-4/A, Summary of the Proxy Statement/Prospectus — Merger Consideration, page 21", "relevance_score": 5}], "default_option": [], "election_deadline": [], "merger_subsidiary": [{"quote": "Trailblazer Merger Sub, Ltd., an Israeli company and a direct, wholly owned subsidiary of Trailblazer (“Merger Sub”)", "location": "S-4/A, preliminary proxy statement/prospectus", "relevance_score": 5}], "cash_consideration_qualifications": [{"quote": "Any holder of a share of Company Capital Shares who would otherwise be entitled to receive a fraction of a share of Parent Common Stock (after aggregating all fractional shares of Parent Common Stock issuable to such holder) shall, in lieu of such fraction of a share, be paid in cash the dollar amount (rounded to the nearest whole cent), without interest, determined by multiplying such fraction by $10.00.", "location": "S-4/A, Annex A — Merger Agreement, Section 3.8", "relevance_score": 5}], "stock_exchange_ratio_type": [{"quote": "“Conversion Ratio” means the ratio (rounded down to four decimal places), equal to the quotient obtained by dividing (a) 10,600,000 shares of Holdings Common Stock constituting the Aggregate Merger Consideration by (b) Cyabra’s outstanding shares, on a fully-diluted basis.", "location": "S-4/A, Frequently Used Terms, page 2", "relevance_score": 5}], "stock_exchange_ratio_qualifications": [{"quote": "“Conversion Ratio” means the ratio (rounded down to four decimal places), equal to the quotient obtained by dividing (a) 10,600,000 shares of Holdings Common Stock constituting the Aggregate Merger Consideration by (b) Cyabra’s outstanding shares, on a fully-diluted basis.", "location": "S-4/A, Frequently Used Terms, page 2", "relevance_score": 5}, {"quote": "The shares comprising the Aggregate Merger Consideration and Conversion Ratio shall be adjusted to reflect appropriately the effect of any stock split, reverse stock split, stock dividend, recapitalization, reclassification, combination, exchange of shares or other like change with respect to Parent Common Stock occurring prior to the date the shares comprising the Aggregate Merger Consideration are issued.", "location": "S-4/A, Annex A — Merger Agreement, Section 3.7", "relevance_score": 5}, {"quote": "No fractional shares of Parent Common Stock, or certificates or scrip representing fractional shares of Parent Common Stock, will be issued upon the conversion of the Company Capital Shares pursuant to the Merger, and such fractional share interests will not entitle the owner thereof to vote or to any rights of a shareholder of Parent. Any holder of a share of Company Capital Shares who would otherwise be entitled to receive a fraction of a share of Parent Common Stock (after aggregating all fractional shares of Parent Common Stock issuable to such holder) shall, in lieu of such fraction of a share, be paid in cash the dollar amount (rounded to the nearest whole cent), without interest, determined by multiplying such fraction by $10.00.", "location": "S-4/A, Annex A — Merger Agreement, Section 3.8", "relevance_score": 5}], "other_consideration": [{"quote": "In addition to the base merger consideration, Cyabra shareholders and holders of Cyabra Options may also receive up to an aggregate of 3,000,000 shares of Holdings Common Stock in three equal installments (the “Earnout Shares”). The Earnout Shares will be issued to Cyabra shareholders and holders of Cyabra Options upon occurrence of certain triggering events (based on the achievement of certain price targets of Holdings Common Stock following the Closing).", "location": "S-4/A, Questions and Answers About the Proposals — What is the consideration being paid to the shareholders of Cyabra?, page 7", "relevance_score": 5}, {"quote": "From and after the period commencing on the six month anniversary of the Closing until December 31, 2026, (the “First Calculation Period”), in the event that over any 20 consecutive trading days within any 30-trading day period during the First Calculation Period the daily volume weighted average price (the “VWAP”) of the shares of Holdings Common Stock is greater than or equal to $15.00 per share (the “First Earnout Event”), promptly after the occurrence of the First Earnout Event, the persons that were Cyabra securityholders immediately prior to the Effective Time (the “Earnout Securityholders”) shall be entitled to receive their pro rata portion of one third of 3,000,000 shares of Holdings Common Stock (the “Incentive Merger Consideration”) as additional consideration for the Business Combination.", "location": "S-4/A, Summary of the Proxy Statement/Prospectus — Earnout, page 22", "relevance_score": 5}, {"quote": "From and after the six month anniversary of the Closing until December 31, 2027 (the “Second Calculation Period”), in the event that over any 20 trading days within any 30-trading day period during the Second Calculation Period the daily VWAP of the shares of Holdings Common Stock is greater than or equal to $20.00 per share (the “Second Earnout Event”), promptly after the occurrence of the Second Earnout Event, Earnout Securityholders shall be entitled to receive their pro rata portion of an additional one third of the Incentive Merger Consideration as additional consideration for the Business Combination.", "location": "S-4/A, Summary of the Proxy Statement/Prospectus — Earnout, page 22", "relevance_score": 5}, {"quote": "From and after the six month anniversary of the Closing until December 31, 2029 (the “Third Calculation Period”), in the event that over any 20 trading days within any 30-trading day period during the Third Calculation Period the daily VWAP of the shares of Holdings Common Stock is greater than or equal to $25.00 per share (the “Third Earnout Event”), promptly after the occurrence of the Third Earnout Event, the Earnout Securityholders shall be entitled to receive their pro rata portion of the final one third of the Incentive Merger Consideration as additional consideration for the Business Combination.", "location": "S-4/A, Summary of the Proxy Statement/Prospectus — Earnout, pages 22–23", "relevance_score": 5}], "expected_closing": [{"quote": "The Closing is expected to take place (a) no later than two (2) business days following the satisfaction or waiver of the conditions described below under the section titled “Proposal 1 — The Merger Proposal — The Merger Agreement — Conditions to Closing”; or (b) such other date as agreed to by the parties to the Merger Agreement in writing, in each case, subject to the satisfaction or waiver of the Closing conditions.", "location": "S-4/A, Questions and Answers About the Proposals — When is the Business Combination expected to be completed?, page 15", "relevance_score": 5}], "event_status_details": [{"quote": "On November 6, 2025, the parties thereto amended the Merger Agreement to, among other things:
(i) amend the provision related to the PIPE Investment to reflect that the PIPE Investors (as defined below) will receive Holdings Series B Preferred Stock and not Holdings Common Stock;
(ii) amend the Base Purchase Price from $70,000,000 to $106,000,000;
(iii) amend the First Calculation Period from December 31, 2025 to December 31, 2026; and
(iv) amend the Outside Date from March 1, 2025 to February 1, 2026.", "location": "S-4/A, Summary of the Proxy Statement/Prospectus — Amendments to the Merger Agreement, page 24", "relevance_score": 5}], "agreement_name": [{"quote": "“Merger Agreement” means the Merger Agreement dated July 22, 2024 (as amended on November 11, 2024, November 6, 2025, and as it may be further amended, supplemented or otherwise modified from time to time), by and among Trailblazer, Holdings, Merger Sub and Cyabra.", "location": "S-4/A, Frequently Used Terms, page 3", "relevance_score": 5}], "agreement_date": [{"quote": "“Merger Agreement” means the Merger Agreement dated July 22, 2024 (as amended on November 11, 2024, November 6, 2025, and as it may be further amended, supplemented or otherwise modified from time to time), by and among Trailblazer, Holdings, Merger Sub and Cyabra.", "location": "S-4/A, Frequently Used Terms, page 3", "relevance_score": 5}], "original_filing_date": [], "related_entities": [{"quote": "On March 12, 2020, the Company established a wholly owned U.S. subsidiary Cyabra Strategy Inc. (the “subsidiary”), for marketing and distribution activity.", "location": "S-4/A, Cyabra Strategy Ltd. and its subsidiary — Notes to Consolidated Financial Statements, Note 1, page F-73", "relevance_score": 5}], "security_identifiers": []}

