k_exchange_ratio_type": [{"quote": "“Company Exchange Ratio” means the quotient (expressed as a number) of (a) the Equity Value divided by (b) the Fully-Diluted Company Shares, divided by (c) ten dollars ($10.00). For illustration purposes only, assuming the Equity Value is $1,257,335,540 and the sum of the Fully-Diluted Company Shares is 27,240,928, the Company Exchange Ratio would be 4.615.", "location": "S-4, Annex A, Business Combination Agreement — Article I, Definitions, page A-6", "relevance_score": 5}], "stock_exchange_ratio_qualifications": [{"quote": "Immediately prior to the Securitize Merger Effective Time, pursuant to the organizational documents of Securitize and the Securitize Written Consent, each share of Securitize Preferred Stock that is issued and outstanding as of such time will be automatically converted into one share of Securitize Common Stock (the “Preferred Stock Conversion”).", "location": "S-4, The Business Combination Agreement — Securitize Merger, page 100", "relevance_score": 5}, {"quote": "“Equity Value” means $1,250,000,000 plus the aggregate exercise price of the first tranche of the Company Warrants and the vested Company Equity Awards that are included in the calculation of Fully-Diluted Company Shares (which, for the avoidance of doubt, shall not include any exercise price or other adjustments in respect of the B8 Convertible Promissory Notes Fully-Diluted Company Shares or the NHTV Fully-Diluted Company Shares).", "location": "S-4, Annex A, Business Combination Agreement — Article I, Definitions, page A-9", "relevance_score": 5}, {"quote": "Notwithstanding anything to the contrary contained herein, no fraction of a share of PubCo Common Stock will be issued by PubCo by virtue of this Agreement or the Transactions, and each Person who would otherwise be entitled to a fraction of a share of PubCo Common Stock (after aggregating all fractional shares of PubCo Common Stock that otherwise would be received by such holder) shall instead have the number of shares of PubCo Common Stock issued to such Person rounded down in the aggregate to the nearest whole share of PubCo Common Stock (without payment in lieu of such fractional shares).", "location": "S-4, Annex A, Business Combination Agreement — Section 2.11(g), page A-30", "relevance_score": 5}], "other_consideration": [{"quote": "“Company Earnout Shares” means 6,250,000 shares of PubCo Common Stock.", "location": "S-4, Annex A, Business Combination Agreement — Article I, Definitions, page A-6", "relevance_score": 5}, {"quote": "During the period commencing on the ninetieth (90th) day following Closing and ending on the fifth (5th) anniversary of the Closing Date (the “Measurement Period”), the Company Earnout Stockholders shall have the right to receive their respective Stockholder Earnout Portion of the Company Earnout Shares", "location": "S-4, Annex A, Business Combination Agreement — Section 2.16(a), page A-32", "relevance_score": 5}, {"quote": "One-third (1/3) of the total Company Earnout Shares shall be issued in the event that the Measurement Period VWAP shall equal or exceed fifteen dollars ($15.00) for any twenty (20) Trading Days within a thirty (30) Trading Day period during the Measurement Period;
(ii) Issuance Threshold II: One-third (1/3) of the total Company Earnout Shares shall be issued in the event that the Measurement Period VWAP shall equal or exceed twenty dollars ($20.00) for any twenty (20) Trading Days within a thirty (30) Trading Day period during the Measurement Period; and
(iii) Issuance Threshold III: One-third (1/3) of the total Company Earnout Shares shall be issued in the event that the Measurement Period VWAP shall equal or exceed twenty-five dollars ($25.00) for any twenty (20) Trading Days within a thirty (30) Trading Day period during the Measurement Period.", "location": "S-4, Annex A, Business Combination Agreement — Section 2.16(c), page A-32", "relevance_score": 5}], "expected_closing": [{"quote": "It is currently anticipated that the Business Combination will be consummated promptly following the Meeting, which is set for , 2026.", "location": "S-4, Questions and Answers About the Proposals, page xxxvii", "relevance_score": 5}], "event_status_details": [{"quote": "On October 27, 2025, CEPT, Securitize, PubCo, SPAC Merger Sub, and Company Merger Sub, entered into the Business Combination Agreement. Pursuant to the Business Combination Agreement, and subject to the terms and conditions set forth therein, on the Closing Date, CEPT will merge with and into SPAC Merger Sub, with SPAC Merger Sub continuing as the surviving entity and Company Merger Sub will merge with and into Securitize, with Securitize continuing as the surviving entity.", "location": "S-4, Summary of the Proxy Statement/Prospectus — The Business Combination Agreement, page 2", "relevance_score": 5}], "agreement_name": [{"quote": "“Business Combination Agreement” means the Business Combination Agreement, dated as of October 27, 2025, by and among CEPT, Securitize, PubCo, Company Merger Sub and SPAC Merger Sub (and as may be amended and/or amended and restated), a copy of which is attached hereto as Annex A.", "location": "S-4, Certain Defined Terms, page vii", "relevance_score": 5}], "agreement_date": [{"quote": "“Business Combination Agreement” means the Business Combination Agreement, dated as of October 27, 2025, by and among CEPT, Securitize, PubCo, Company Merger Sub and SPAC Merger Sub (and as may be amended and/or amended and restated), a copy of which is attached hereto as Annex A.", "location": "S-4, Certain Defined Terms, page vii", "relevance_score": 5}], "original_filing_date": [], "related_entities": [{"quote": "“Company Merger Sub” means Senna Merger Sub, Inc., a Delaware corporation and a wholly owned subsidiary of CEPT.", "location": "S-4, Certain Defined Terms, page viii", "relevance_score": 5}, {"quote": "“SPAC Merger Sub” means Pinecrest Merger Sub, a Cayman Islands exempted company and wholly-owned subsidiary of PubCo.", "location": "S-4, Summary of the Proxy Statement/Prospectus — Parties to the Business Combination, page 2", "relevance_score": 5}], "security_identifiers": []}

