{"acquirer": [{"quote": "Prior to the Effective Time, Parent shall appoint Equiniti Trust Company, LLC, or one of its Affiliates, as the paying agent (or such other nationally recognized paying agent designated by Parent and reasonably acceptable to the Company) (the “Paying Agent”) to act as agent for the Company’s stockholders who shall become entitled to receive the Per Share Merger Consideration.", "location": "PREM14A, Annex A, Section 2.04(a), page A-14", "relevance_score": 5}, {"quote": "THIS AGREEMENT AND PLAN OF MERGER (this “Agreement”), dated as of January 20, 2026, is entered into by and among Smithfield Foods, Inc., a Virginia corporation (“Parent”), Boardwalk Merger Sub Inc., a Delaware corporation and wholly-owned subsidiary of Parent (“Merger Sub”), and Nathan’s Famous, Inc., a Delaware corporation (the “Company”).", "location": "PREM14A, Annex A, Agreement and Plan of Merger, page A-1", "relevance_score": 5}], "target": [{"quote": "At the Effective Time, Merger Sub shall be merged with and into the Company in accordance with the DGCL, whereupon the separate existence of Merger Sub shall cease, and the Company shall be the surviving corporation in the Merger (the “Surviving Corporation”), and the separate corporate existence of the Company, with all its rights, privileges, immunities, powers and franchises, shall continue unaffected by the Merger.", "location": "PREM14A, Annex A, Section 2.02(c), page A-14", "relevance_score": 5}, {"quote": "THIS AGREEMENT AND PLAN OF MERGER (this “Agreement”), dated as of January 20, 2026, is entered into by and among Smithfield Foods, Inc., a Virginia corporation (“Parent”), Boardwalk Merger Sub Inc., a Delaware corporation and wholly-owned subsidiary of Parent (“Merger Sub”), and Nathan’s Famous, Inc., a Delaware corporation (the “Company”).", "location": "PREM14A, Annex A, Agreement and Plan of Merger, page A-1", "relevance_score": 5}], "consideration_type": [{"quote": "each share of Company Common Stock issued and outstanding immediately prior to the Effective Time shall be automatically canceled and converted into the right to receive $102.00 in cash without interest (the “Per Share Merger Consideration”).", "location": "PREM14A, Annex A, Section 2.03(a), page A-14", "relevance_score": 5}], "cash_consideration": [{"quote": "each share of Company Common Stock issued and outstanding immediately prior to the Effective Time shall be automatically canceled and converted into the right to receive $102.00 in cash without interest (the “Per Share Merger Consideration”).", "location": "PREM14A, Annex A, Section 2.03(a), page A-14", "relevance_score": 5}], "stock_exchange_ratio": [{"quote": "If the Merger is consummated, you will not own any shares in Nathan’s, the Surviving Corporation or Parent.", "location": "PREM14A, Questions and Answers About the Merger and the Special Meeting, page 15", "relevance_score": 5}], "shareholder_vote_date": [], "closing_conditions": [{"quote": "The respective obligations of the Company, Parent and Merger Sub to consummate the Merger are subject to the satisfaction of or, to the extent permitted by Applicable Law, waiver of, at or prior to the Closing, the following conditions:
