{"acquirer": [{"quote": "Veolia, and Liberty Merger Sub Inc., a Delaware corporation and wholly owned indirect subsidiary of Veolia (“Merger Sub”), pursuant to which, on the terms and subject to the conditions set forth in the Merger Agreement, Veolia will acquire CE Holdings through the merger of Merger Sub with and into CE Holdings", "location": "enviri-proxy.htm, Notice of Special Meeting of Stockholders, page 5", "relevance_score": 5}, {"quote": "Pursuant to the Merger Agreement, Veolia will cause CE Holdings to repay immediately following the Effective Time", "location": "enviri-proxy.htm, The Separation Agreement — The Reorganization, page 105", "relevance_score": 2}], "target": [{"quote": "Merger Sub will merge with and into CE Holdings, with CE Holdings being the surviving company in the Merger", "location": "enviri-proxy.htm, Summary — The Merger, page 13", "relevance_score": 5}, {"quote": "CE Holdings is a Delaware corporation and was formed on November 4, 2025 under the name CLEH, Inc.", "location": "enviri-proxy.htm, Parties to the Merger — CLEH, INC., page 11", "relevance_score": 5}], "consideration_type": [{"quote": "each share of CE Holdings common stock (formerly Enviri common stock) that is outstanding immediately prior to the Effective Time (other than (i) shares of CE Holdings common stock owned by CE Holdings as treasury shares, (ii) shares of CE Holdings common stock owned by Veolia or Merger Sub and (iii) any dissenting shares (collectively, the “Excluded Shares”)) will be cancelled and automatically exchanged for an amount per share, in cash, not to be less than $14.50 per share and not to exceed $16.50 per share without the consent of Veolia", "location": "enviri-proxy.htm, The Merger Agreement — Treatment of Enviri Common Stock, CE Holdings Common Stock, and Enviri LTI Awards, page 86", "relevance_score": 5}], "cash_consideration": [{"quote": "an amount per share, in cash, not to be less than $14.50 per share and not to exceed $16.50 per share without the consent of Veolia", "location": "enviri-proxy.htm, The Merger Agreement — Treatment of Enviri Common Stock, CE Holdings Common Stock, and Enviri LTI Awards, page 86", "relevance_score": 5}], "stock_exchange_ratio": [], "shareholder_vote_date": [{"quote": "The Special Meeting of stockholders of Enviri will be held online in a virtual format at https://meetnow.global/MRZPGPM, on , 2026, at .", "location": "enviri-proxy.htm, Questions and Answers — When and where is the Special Meeting?, page 20", "relevance_score": 3}], "closing_conditions": [{"quote": "The respective obligations of Enviri, CE Holdings, Enviri LLC, Veolia, and Merger Sub to consummate the Merger are subject to the fulfillment of the following conditions:
