{"acquirer": [{"quote": "The Merger will be consummated with the Company surviving as a wholly owned subsidiary of Parent and thereby effectuating the acquisition of the Company by Parent.", "location": "PREM14A, shareholder letter", "relevance_score": 5}, {"quote": "Prior to the Effective Time, Parent will make available to the Paying Agent the aggregate Merger Consideration to be paid in respect of the Certificated Shares and the Uncertificated Shares", "location": "PREM14A, The Merger Agreement—Exchange and Payment Procedures, page 68", "relevance_score": 5}, {"quote": "SP Evolution HoldCo II, LLC is a Delaware limited liability company.", "location": "PREM14A, The Companies, page 27", "relevance_score": 5}], "target": [{"quote": "At the Effective Time, Merger Sub will merge with and into the Company (the “Merger”) in accordance with the CGCL and the DLLCA, whereupon the separate existence of Merger Sub will cease, and the Company will be the surviving corporation as a wholly owned Subsidiary of Parent (the “Surviving Corporation”).", "location": "PREM14A, Annex A—Merger Agreement, Section 2.01, page 14", "relevance_score": 5}, {"quote": "AGREEMENT AND PLAN OF MERGER (as amended in accordance with the terms and conditions hereof, this “Agreement”) dated as of June 15, 2026, among Simulations Plus, Inc., a California corporation (the “Company”), SP Evolution HoldCo II, LLC, a Delaware limited liability company (“Parent”), and SP Evolution BidCo II, LLC, a Delaware limited liability company and a wholly owned subsidiary of Parent (“Merger Sub”).", "location": "PREM14A, Annex A—Merger Agreement, preamble", "relevance_score": 5}], "consideration_type": [{"quote": "At the Effective Time, each Company Common Share outstanding immediately prior to the Effective Time (other than Cancelled Shares and Dissenting Shares, each as described below) will automatically be converted into the right to receive $18.50 in cash, without interest.", "location": "PREM14A, The Merger Agreement—Conversion of Company Common Shares, page 67", "relevance_score": 5}], "cash_consideration": [{"quote": "At the Effective Time, each Company Common Share outstanding immediately prior to the Effective Time (other than Cancelled Shares and Dissenting Shares, each as described below) will automatically be converted into the right to receive $18.50 in cash, without interest.", "location": "PREM14A, The Merger Agreement—Conversion of Company Common Shares, page 67", "relevance_score": 5}], "stock_exchange_ratio": [{"quote": "You will not receive any shares of the Surviving Corporation or any other equity interest in Parent or any of its affiliates.", "location": "PREM14A, Questions and Answers, page 16", "relevance_score": 5}], "shareholder_vote_date": [{"quote": "The Special Meeting will be held on [●] beginning at 5:00 p.m. Eastern Time (with log-in beginning at 4:45 p.m. Eastern Time), unless postponed to a later date.", "location": "PREM14A, Questions and Answers, page 15", "relevance_score": 5}], "closing_conditions": [{"quote": "The obligations of the Company, Parent and Merger Sub to consummate the Merger are subject to the satisfaction (or, to the extent permitted by Applicable Law, written waiver by Parent and the Company) of the following conditions:
