{"acquirer": [{"quote": "each share of common stock, $0.001 par value per share, of M2i Global (“M2i Global Common Stock”) issued and outstanding immediately prior to the Effective Time will be converted into the right to receive a number of shares of Class A common stock, par value $0.0001 per share of Volato", "location": "forms-4a.htm, preliminary proxy statement/prospectus", "relevance_score": 5}], "target": [{"quote": "Merger Sub will merge with and into M2i Global, with M2i Global surviving the merger as a wholly-owned subsidiary of Volato", "location": "forms-4a.htm, preliminary proxy statement/prospectus", "relevance_score": 5}], "consideration_type": [{"quote": "each share of M2i Global Common Stock issued and outstanding immediately prior to the Effective Time will be converted into the right to receive a number of shares of Volato Common Stock equal to 85% of the Volato Common Stock on an as converted and fully diluted basis at the Effective Time", "location": "forms-4a.htm, The Merger Agreement — Terms of the Merger; Merger Consideration, page 71", "relevance_score": 5}], "cash_consideration": [{"quote": "No cash will be paid for any fractional share eliminated by such rounding.", "location": "forms-4a.htm, The Merger Agreement — Terms of the Merger; Merger Consideration, page 72", "relevance_score": 3}, {"quote": "each share of Company Capital Stock outstanding immediately prior to the Effective Time shall be converted solely into the right to receive the Merger Consideration.", "location": "forms-4a.htm, Annex A, Section 2.5(a), page A-17", "relevance_score": 5}, {"quote": "“Merger Consideration” means for each share of Company Common Stock that is issued and outstanding immediately prior to the Effective Time, the number of shares of Volato Common Stock to be issued in exchange for such share of Company Common Stock", "location": "forms-4a.htm, Annex A, Section 1.1, page A-8", "relevance_score": 5}], "stock_exchange_ratio": [{"quote": "each share of M