ualifications": [{"quote": "Notwithstanding anything in this Agreement to the contrary, no fractional shares of Domesticated Acquiror Class A Common Stock shall be issued in the Merger.", "location": "apadu-20260409.htm, Annex A, Section 3.1(f)", "relevance_score": 5}], "other_consideration": [{"quote": "the Apeiron Holders and those Persons designated by Apeiron Investment Group Limited in its sole discretion (collectively, the “Class B Holders”), in each case, as designated in the Allocation Statement, shall be issued a number of shares of Acquiror Class B Common Stock such that as of immediately following the consummation of the transactions contemplated hereby, the Class B Holders shall have at least 95% of the voting power of the capital stock of the Surviving Corporation on a fully-diluted basis (the “Class B Issued Shares”).", "location": "apadu-20260409.htm, Annex A, Section 3.1(b)", "relevance_score": 5}], "expected_closing": [{"quote": "Approximate date of commencement of proposed sale of the securities to the public: As soon as practicable after this registration statement is declared effective and all other conditions to the Business Combination described in the enclosed proxy statement/prospectus have been satisfied or waived.", "location": "apadu-20260409.htm, registration statement cover", "relevance_score": 3}, {"quote": "the Closing will take place at 8:00 a.m., New York time, on the date that is the third business day after the satisfaction or waiver of the conditions set forth in the Business Combination Agreement (other than those conditions that by their nature are to be satisfied at the Closing, but subject to the satisfaction or waiver of those conditions), unless another time or date is mutually agreed to in writing by the parties.", "location": "apadu-20260409.htm, The BCA Proposal—Closing", "relevance_score": 5}], "event_status_details": [{"quote": "On November 26, 2025, A Paradise entered into the Business Combination Agreement with Merger Sub and Enhanced, pursuant to which, among other things, following the Domestication, (i) Merger Sub will merge with and into Enhanced, the separate corporate existence of Merger Sub will cease and Enhanced will be the surviving corporation and a wholly owned subsidiary of A Paradise, (ii) Enhanced will merge with and into A Paradise, the separate corporate existence of Enhanced will cease and A Paradise will be the surviving corporation, and (iii) A Paradise will change its name to “Enhanced Group Inc.”", "location": "apadu-20260409.htm, The BCA Proposal—General Description of the Business Combination", "relevance_score": 5}], "agreement_name": [{"quote": "“Business Combination Agreement” are to the Agreement and Plan of Merger, dated as of November 26, 2025, by and among A Paradise, Merger Sub and Enhanced", "location": "apadu-20260409.htm, Glossary", "relevance_score": 5}, {"quote": "BUSINESS COMBINATION AGREEMENT", "location": "apadu-20260409.htm, Annex A", "relevance_score": 5}], "agreement_date": [{"quote": "This Business Combination Agreement, dated as of November 26, 2025 (this “Agreement”), is made and entered into by and among A Paradise Acquisition Corp., a blank check company incorporated in the British Virgin Islands as a business company with limited liability (which shall migrate to and domesticate as a Texas corporation prior to the Closing Date pursuant to the terms and conditions of this Agreement) (“Acquiror”), A Paradise Merger Sub I, Inc., a Cayman Islands exempted company and a direct wholly owned Subsidiary of Acquiror (“Merger Sub”), and Enhanced Ltd, a Cayman Islands exempted company with limited liability (the “Company” and together with Acquiror and Merger Sub, the “Parties”).", "location": "apadu-20260409.htm, Annex A, Business Combination Agreement", "relevance_score": 5}], "original_filing_date": [], "related_entities": [{"quote": "A Paradise Merger Sub I, Inc., a Cayman Islands exempted company and a direct wholly owned Subsidiary of 